"use client";
import { BrandMark } from "@/components/BrandMark";

import { useCallback, useEffect, useMemo, useState } from "react";
import type { ChangeEvent, FormEvent, ReactNode } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { formatRupees } from "@/lib/agri-data";

const API_BASE = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001/api/v1";
const API_ORIGIN = new URL(API_BASE).origin;
type Tab = "overview" | "orders" | "retailers" | "products" | "inventory" | "purchases" | "suppliers" | "finance" | "ledger" | "delivery" | "returns" | "reports" | "marketing" | "offers" | "notifications" | "staff" | "users" | "activity" | "settings" | "catalog" | "home-cards" | "mobile-home" | "support";
type ProductStatus = "DRAFT" | "PENDING_REVIEW" | "APPROVED" | "REJECTED" | "ARCHIVED";
type AdminOffer = { id: string; sellerSku: string; price: number | string; mrp: number | string | null; minimumOrderQuantity: number; stockOnHand: number; reservedQuantity: number; commissionRate: number | string; isActive: boolean; source: string; serviceAreas?: { pinCode: string }[]; seller: { id: string; name: string; type: string } };
type AdminProduct = { id: string; name: string; slug: string; description: string | null; imageUrl: string | null; packSize: string; unit: string; taxRate: number | string; status: ProductStatus; category: { id: string; name: string }; brand: { id: string; name: string } | null; offers: AdminOffer[] };
type Organization = { id: string; name: string; type: string; email: string | null; phone: string | null; verificationStatus: string; verificationReason: string | null; createdAt: string; _count: { users: number; kycDocuments: number } };
type Account = { id: string; name: string; email: string; phone: string | null; role: string; status: string; adminPermissions?: string[]; isSuperAdmin?: boolean; createdAt: string; organization: { id: string; name: string; type: string; verificationStatus: string } | null };
type AccountDetail = Omit<Account, "organization"> & { emailVerifiedAt: string | null; phoneVerifiedAt: string | null; organization: (NonNullable<Account["organization"]> & { verificationReason: string | null; businessEntityType: string | null; gstin: string | null; shopPinCode: string | null; shopCity: string | null; shopDistrict: string | null; shopState: string | null; shopNumber: string | null; shopArea: string | null; shopLandmark: string | null; deliveryAddresses: { id: string; label: string; recipientName: string; phone: string; address: string; area: string; district: string; pinCode: string; isDefault: boolean }[]; kycDocuments: { id: string; documentType: string; originalName: string; reviewStatus: string; reviewReason: string | null; createdAt: string }[]; certificateApplications: { id: string; certificate: string; purpose: string | null; status: string; reviewReason: string | null; createdAt: string }[]; wallet: { balance: string | number; coinBalance: number; transactions: { id: string; type: string; amount: string | number; coinDelta: number; description: string; createdAt: string }[] } | null; retailerOrders: { id: string; orderNumber: string; status: string; total: string | number; createdAt: string; fulfillments: { id: string; status: string; seller: { name: string }; lines: { productNameSnapshot: string; quantity: number; lineTotal: string | number }[] }[]; returnRequests: { id: string; status: string; reason: string; reviewReason: string | null }[] }[] }) | null };
type Order = { id: string; orderNumber: string; status: string; paymentMethod?: string | null; total: number | string; createdAt: string; deliveryName: string; deliveryDistrict: string; retailer: { id: string; name: string }; payments?: { id: string; status: string; provider: string | null; amount: number | string }[]; returnRequests?: { id: string; status: string; reason: string; reviewReason: string | null }[]; fulfillments: { id: string; status: string; seller: { id: string; name: string }; lines: { quantity: number; productNameSnapshot: string }[] }[] };
type Named = { id: string; name: string; slug: string; description?: string | null; imageUrl?: string | null; isActive?: boolean; _count?: { products: number } };
type ProductForm = { name: string; categoryId: string; brandId: string; description: string; imageUrl: string; packSize: string; unit: string; price: string; mrp: string; taxRate: string; sellerSku: string; servicePinCodes: string; minimumOrderQuantity: string; stockOnHand: string; status: ProductStatus };
type InventoryRecord = { id: string; sellerSku: string; source: string; price: number | string; mrp: number | string | null; minimumOrderQuantity: number; stockOnHand: number; reservedQuantity: number; commissionRate: number | string; isActive: boolean; product: { id: string; name: string; category: { name: string } }; seller: { name: string } };
type DeliveryRecord = { id: string; status: string; trackingNumber: string | null; fulfillmentOrder: { customerOrder: { orderNumber: string; deliveryName: string; deliveryDistrict: string; deliveryPinCode: string } } };
type LedgerRecord = { payments: { id: string; amount: number | string; status: string; provider: string | null; createdAt: string; customerOrder: { orderNumber: string; retailer: { name: string } } }[]; walletTransactions: { id: string; amount: number | string; type: string; description: string; createdAt: string; wallet: { organization: { name: string } } }[] };
type AdminNotification = { id: string; title: string; body: string; audience: string; isActive: boolean; createdAt: string; _count: { recipients: number } };
type AdminSetting = { key: string; value: Record<string, unknown>; updatedAt: string };
type AdminPromotion = { id: string; title: string; body: string; startsAt: string; endsAt: string; isActive: boolean; type: "FESTIVAL" | "BULK" | "REWARDS"; discountPercent: number | string | null; minimumOrderQuantity: number | null; coinsPer100: number };
type SupportTicket = { id: string; subject: string; message: string; status: "OPEN" | "IN_PROGRESS" | "RESOLVED" | "CLOSED"; adminReply: string | null; createdAt: string; updatedAt: string; organization: { id: string; name: string; email: string | null; phone: string | null } };
type PurchaseLine = { id: string; productId: string; quantity: number; receivedQuantity: number; unitCost: number | string; product: { id: string; name: string; packSize: string; unit: string } };
type PurchaseOrder = { id: string; orderNumber: string; status: string; total: number | string; note: string | null; supplier: { id: string; name: string; phone?: string | null; email?: string | null }; lines: PurchaseLine[]; createdAt: string };
type FinanceData = { accounts: { id: string; name: string; type: string; bankName: string | null; accountNumberLast4: string | null; currentBalance: number | string; isActive: boolean }[]; transactions: { id: string; type: string; amount: number | string; category: string | null; reference: string | null; note: string | null; transactionDate: string; account: { name: string; type: string }; partyOrganization: { id: string; name: string; type: string } | null; customerOrder: { orderNumber: string } | null; purchaseOrder: { orderNumber: string } | null }[]; retailerDues: { id: string; name: string; due: number | string }[]; supplierDues: { id: string; name: string; due: number | string }[]; retailerInvoices: { orderId: string; orderNumber: string; retailerId: string; retailerName: string; total: number | string; due: number | string }[]; supplierPayables: { purchaseOrderId: string; orderNumber: string; supplierId: string; supplierName: string; payable: number | string; due: number | string }[]; summary: { retailerDue: number; supplierDue: number; cashAndBank: number; expenses: number; collections: number }; monthlySales: { month: string; total: number; orders: number }[] };
type AdminReports = { orders: { status: string; _count: { _all: number } }[]; orderValues: { count: number; revenue: number }; products: { status: string; _count: { _all: number } }[]; inventory: { offers: number; unitsOnHand: number; lowStockOffers: number }; users: { role: string; _count: { _all: number } }[]; paymentTotals: { status: string; _sum: { amount: number | string | null }; _count: { _all: number } }[] };
type AuditRow = { id: string; action: string; entityType: string; entityId: string; before: unknown; after: unknown; ipAddress: string | null; createdAt: string; actor: { id: string; name: string; email: string; role: string } | null };
type ErrorRecord = { id: string; requestId: string; method: string; path: string; statusCode: number; errorType: string; createdAt: string; actor: { id: string; name: string; role: string } | null };
type BackupRecord = { id: string; fileName: string; status: string; sizeBytes: number | null; errorCode: string | null; createdAt: string; finishedAt: string | null; actor: { id: string; name: string } | null };
type ReturnRecord = { id: string; reason: string; status: string; reviewReason: string | null; requestedAt: string; customerOrder: { id: string; orderNumber: string; retailer: { id: string; name: string; phone: string | null }; total: number | string; status: string } };
type BusinessDashboard = { pendingOrders: number; lowStock: number; expiringProducts: number; expiringLots: { id: string; quantity: number; batchNumber: string | null; expiresAt: string | null; offer: { product: { name: string }; seller: { name: string } } }[]; deliveryStatus: { status: string; _count: { _all: number } }[]; monthlySales: { month: string; total: number; orders: number }[]; retailerDue: number; supplierDue: number; cashAndBank: number; expenses: number; collections: number };

const emptyForm = (categoryId = ""): ProductForm => ({ name: "", categoryId, brandId: "", description: "", imageUrl: "", packSize: "", unit: "piece", price: "", mrp: "", taxRate: "0", sellerSku: `AO-${Date.now().toString().slice(-7)}`, servicePinCodes: "", minimumOrderQuantity: "1", stockOnHand: "0", status: "APPROVED" });
const nav: { id: Tab; label: string; icon: string }[] = [
  { id: "overview", label: "Dashboard / Overview", icon: "▦" },
  { id: "orders", label: "Orders", icon: "▣" },
  { id: "retailers", label: "Retailers", icon: "♙" },
  { id: "products", label: "Products & Stock", icon: "▤" },
  { id: "purchases", label: "Purchase & Suppliers", icon: "⇅" },
  { id: "finance", label: "Finance & Accounts", icon: "₹" },
  { id: "delivery", label: "Delivery", icon: "⇢" },
  { id: "returns", label: "Returns & Claims", icon: "↶" },
  { id: "reports", label: "Reports & Analytics", icon: "◷" },
  { id: "marketing", label: "Marketing & Promotions", icon: "%" },
  { id: "notifications", label: "Notifications", icon: "♧" },
  { id: "staff", label: "Staff & Permissions", icon: "♟" },
  { id: "activity", label: "Activity Log", icon: "≡" },
  { id: "settings", label: "Settings", icon: "⚙" },
];
const legacyNav: { id: Tab; label: string; parent: Tab; permission: string }[] = [
  { id: "inventory", label: "Inventory movements", parent: "products", permission: "INVENTORY" },
  { id: "suppliers", label: "Supplier directory", parent: "purchases", permission: "RETAILERS" },
  { id: "ledger", label: "Payment & ledger history", parent: "finance", permission: "FINANCE" },
  { id: "offers", label: "Offers & promotions", parent: "marketing", permission: "CATALOG" },
  { id: "users", label: "All user accounts", parent: "staff", permission: "USERS" },
  { id: "support", label: "Support tickets", parent: "retailers", permission: "RETAILERS" },
  { id: "catalog", label: "Categories & brands", parent: "settings", permission: "CATALOG" },
  { id: "home-cards", label: "Homepage card images", parent: "settings", permission: "CATALOG" },
  { id: "mobile-home", label: "Mobile App Home", parent: "settings", permission: "SETTINGS" },
];
const HOME_CARD_SETTINGS = [
  { slug: "fertilizers", name: "Fertilizers", defaultImage: "/products/fertilizer-dap.webp" },
  { slug: "seeds", name: "Seeds", defaultImage: "/products/seed-variety.webp" },
  { slug: "pesticides", name: "Pesticides", defaultImage: "/products/pesticide-hamla.webp" },
  { slug: "equipment", name: "Equipment", defaultImage: "" },
];

export function AdminControlPanel() {
  const router = useRouter();
  const [tab, setTab] = useState<Tab>("overview");
  const [token, setToken] = useState("");
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [overview, setOverview] = useState<Record<string, number>>({});
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [accountDetail, setAccountDetail] = useState<AccountDetail | null>(null);
  const [orders, setOrders] = useState<Order[]>([]);
  const [categories, setCategories] = useState<Named[]>([]);
  const [brands, setBrands] = useState<Named[]>([]);
  const [homeCategoryCards, setHomeCategoryCards] = useState<Record<string, string>>({});
  const [inventory, setInventory] = useState<InventoryRecord[]>([]);
  const [deliveries, setDeliveries] = useState<DeliveryRecord[]>([]);
  const [ledger, setLedger] = useState<LedgerRecord>({ payments: [], walletTransactions: [] });
  const [reports, setReports] = useState<AdminReports>({ orders: [], orderValues: { count: 0, revenue: 0 }, products: [], inventory: { offers: 0, unitsOnHand: 0, lowStockOffers: 0 }, users: [], paymentTotals: [] });
  const [notifications, setNotifications] = useState<AdminNotification[]>([]);
  const [settings, setSettings] = useState<AdminSetting[]>([]);
  const [promotions, setPromotions] = useState<AdminPromotion[]>([]);
  const [supportTickets, setSupportTickets] = useState<SupportTicket[]>([]);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [financeData, setFinanceData] = useState<FinanceData | null>(null);
  const [staff, setStaff] = useState<Account[]>([]);
  const [activity, setActivity] = useState<AuditRow[]>([]);
  const [errorRecords, setErrorRecords] = useState<ErrorRecord[]>([]);
  const [backupRecords, setBackupRecords] = useState<BackupRecord[]>([]);
  const [returnRecords, setReturnRecords] = useState<ReturnRecord[]>([]);
  const [businessDashboard, setBusinessDashboard] = useState<BusinessDashboard | null>(null);
  const [adminAccess, setAdminAccess] = useState<{ isSuperAdmin: boolean; adminPermissions: string[] }>({ isSuperAdmin: false, adminPermissions: [] });
  const [homeCardFiles, setHomeCardFiles] = useState<Record<string, File>>({});
  const [homeCardPreviews, setHomeCardPreviews] = useState<Record<string, string>>({});
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<AdminProduct | null>(null);
  const [form, setForm] = useState<ProductForm>(emptyForm());
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState("");
  const [showProductForm, setShowProductForm] = useState(false);
  const [newCategory, setNewCategory] = useState("");
  const [newBrand, setNewBrand] = useState("");

  const api = useCallback(async <T,>(path: string, init: RequestInit = {}): Promise<T> => {
    const headers = new Headers(init.headers);
    headers.set("Authorization", `Bearer ${token}`);
    if (init.body && !(init.body instanceof FormData)) headers.set("Content-Type", "application/json");
    const response = await fetch(`${API_BASE}${path}`, { ...init, headers, cache: "no-store" });
    const body = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(body.message ?? `Request failed (${response.status})`);
    return body as T;
  }, [token]);

  const refresh = useCallback(async () => {
    if (!token) return;
    setLoading(true);
    setError("");
    try {
      const access = await api<{ isSuperAdmin: boolean; adminPermissions: string[] }>("/admin/access");
      setAdminAccess(access);
      const can = (permission: string) => access.isSuperAdmin || access.adminPermissions.includes(permission);
      const [stats, productPage, retailerOrgs, supplierOrgs, userPage, orderPage, catalog, homeCards, inventoryRows, deliveryRows, ledgerRows, reportData, notificationRows, settingRows, promotionRows, purchaseRows, financeRows, staffRows, activityPage, returnRows, businessData, errorRows, backupRows] = await Promise.all([
        can("REPORTS") ? api<Record<string, number>>("/admin/overview") : Promise.resolve({} as Record<string, number>),
        can("CATALOG") ? api<{ data: AdminProduct[] }>("/admin/products?pageSize=100") : Promise.resolve({ data: [] as AdminProduct[] }),
        can("RETAILERS") ? api<{ data: Organization[] }>("/admin/organizations?page=1&type=RETAILER") : Promise.resolve({ data: [] as Organization[] }),
        can("RETAILERS") ? api<{ data: Organization[] }>("/admin/organizations?page=1&type=SUPPLIER") : can("PURCHASING") ? api<{ data: Organization[] }>("/admin/purchases/suppliers") : Promise.resolve({ data: [] as Organization[] }),
        can("USERS") ? api<{ data: Account[]; pagination: { totalPages: number } }>("/admin/users?pageSize=100") : Promise.resolve({ data: [] as Account[], pagination: { totalPages: 1 } }),
        can("ORDERS") ? api<{ data: Order[] }>("/admin/orders?pageSize=100") : Promise.resolve({ data: [] as Order[] }),
        can("CATALOG") ? api<{ categories: Named[]; brands: Named[] }>("/admin/catalog-structure") : Promise.resolve({ categories: [] as Named[], brands: [] as Named[] }),
        can("CATALOG") ? api<Record<string, string>>("/admin/home-category-cards") : Promise.resolve({}),
        can("INVENTORY") ? api<InventoryRecord[]>("/admin/inventory") : Promise.resolve([] as InventoryRecord[]),
        can("DELIVERY") ? api<DeliveryRecord[]>("/admin/deliveries") : Promise.resolve([] as DeliveryRecord[]),
        can("FINANCE") ? api<LedgerRecord>("/admin/ledger") : Promise.resolve({ payments: [], walletTransactions: [] }),
        can("REPORTS") ? api<AdminReports>("/admin/reports") : Promise.resolve({ orders: [], orderValues: { count: 0, revenue: 0 }, products: [], inventory: { offers: 0, unitsOnHand: 0, lowStockOffers: 0 }, users: [], paymentTotals: [] } as AdminReports),
        can("NOTIFICATIONS") ? api<AdminNotification[]>("/admin/notifications") : Promise.resolve([] as AdminNotification[]),
        can("SETTINGS") ? api<AdminSetting[]>("/admin/settings") : Promise.resolve([] as AdminSetting[]),
        can("CATALOG") ? api<AdminPromotion[]>("/admin/promotions") : Promise.resolve([] as AdminPromotion[]),
        can("PURCHASING") ? api<PurchaseOrder[]>("/admin/purchases") : Promise.resolve([] as PurchaseOrder[]),
        can("FINANCE") ? api<FinanceData>("/admin/finance") : Promise.resolve(null as FinanceData | null),
        can("STAFF") ? api<Account[]>("/admin/staff") : Promise.resolve([] as Account[]),
        can("ACTIVITY") ? api<{ data: AuditRow[] }>("/admin/activity?pageSize=100") : Promise.resolve({ data: [] as AuditRow[] }),
        can("ORDERS") ? api<ReturnRecord[]>("/admin/returns") : Promise.resolve([] as ReturnRecord[]),
        can("REPORTS") ? api<BusinessDashboard>("/admin/business-dashboard") : Promise.resolve(null as BusinessDashboard | null),
        can("ACTIVITY") ? api<ErrorRecord[]>("/admin/errors") : Promise.resolve([] as ErrorRecord[]),
        can("SETTINGS") ? api<BackupRecord[]>("/admin/backups") : Promise.resolve([] as BackupRecord[]),
      ]);
      const accountPages = await Promise.all(Array.from({ length: Math.max(0, userPage.pagination.totalPages - 1) }, (_, index) => api<{ data: Account[] }>(`/admin/users?page=${index + 2}&pageSize=100`)));
      setOverview(stats); setBusinessDashboard(businessData); setProducts(productPage.data); setOrganizations([...retailerOrgs.data, ...supplierOrgs.data]); setAccounts([ ...userPage.data, ...accountPages.flatMap((page) => page.data) ]); setOrders(orderPage.data); setCategories(catalog.categories); setBrands(catalog.brands); setHomeCategoryCards(homeCards); setInventory(inventoryRows); setDeliveries(deliveryRows); setLedger(ledgerRows); setReports(reportData); setNotifications(notificationRows); setSettings(settingRows); setPromotions(promotionRows); setPurchaseOrders(purchaseRows); setFinanceData(financeRows); setStaff(staffRows); setActivity(activityPage.data); setReturnRecords(returnRows); setErrorRecords(errorRows); setBackupRecords(backupRows);
      setSupportTickets(await api<SupportTicket[]>("/support/admin/tickets").catch(() => []));
    } catch (cause) {
      const message = cause instanceof Error ? cause.message : "Could not load admin data";
      setError(message);
      if (message.includes("401") || message.toLowerCase().includes("bearer") || message.toLowerCase().includes("expired")) setToken("");
    } finally { setLoading(false); }
  }, [api, token]);

  useEffect(() => { queueMicrotask(() => setToken(window.sessionStorage.getItem("agri-one-access-token") ?? "")); }, []);
  useEffect(() => { queueMicrotask(() => { if (token) void refresh(); else setLoading(false); }); }, [token, refresh]);
  useEffect(() => {
    if (!token) return;
    const sync = () => { if (document.visibilityState === "visible") void refresh(); };
    const timer = window.setInterval(sync, 30_000);
    window.addEventListener("focus", sync);
    return () => { window.clearInterval(timer); window.removeEventListener("focus", sync); };
  }, [token, refresh]);

  const showNotice = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(""), 2600); };
  const run = async (action: () => Promise<void>, success: string) => {
    setBusy(true); setError("");
    try { await action(); showNotice(success); await refresh(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Action failed"); }
    finally { setBusy(false); }
  };
  const filteredProducts = useMemo(() => products.filter((item) => `${item.name} ${item.brand?.name ?? ""} ${item.category.name} ${item.status}`.toLowerCase().includes(search.toLowerCase())), [products, search]);
  const filteredOrgs = useMemo(() => organizations.filter((item) => item.type === (tab === "retailers" ? "RETAILER" : "SUPPLIER") && `${item.name} ${item.email ?? ""} ${item.verificationStatus}`.toLowerCase().includes(search.toLowerCase())), [organizations, search, tab]);
  const filteredOrders = useMemo(() => orders.filter((item) => `${item.orderNumber} ${item.retailer.name} ${item.status}`.toLowerCase().includes(search.toLowerCase())), [orders, search]);
  const filteredAccounts = useMemo(() => accounts.filter((item) => `${item.name} ${item.email} ${item.role} ${item.organization?.name ?? ""} ${item.status}`.toLowerCase().includes(search.toLowerCase())), [accounts, search]);
  const requiredPermission: Partial<Record<Tab, string>> = { overview: "REPORTS", products: "CATALOG", catalog: "CATALOG", "home-cards": "CATALOG", retailers: "RETAILERS", suppliers: "PURCHASING", users: "USERS", staff: "STAFF", orders: "ORDERS", returns: "ORDERS", inventory: "INVENTORY", ledger: "FINANCE", finance: "FINANCE", delivery: "DELIVERY", offers: "CATALOG", marketing: "CATALOG", reports: "REPORTS", notifications: "NOTIFICATIONS", activity: "ACTIVITY", settings: "SETTINGS", purchases: "PURCHASING" };
  const canManageInventory = adminAccess.isSuperAdmin || adminAccess.adminPermissions.includes("INVENTORY");
  const canAccess = (permission: string) => adminAccess.isSuperAdmin || adminAccess.adminPermissions.includes(permission);
  const visibleNav = nav.filter((item) => item.id === "purchases" ? canAccess("PURCHASING") || canAccess("RETAILERS") : item.id === "products" ? canAccess("CATALOG") || canAccess("INVENTORY") : item.id === "settings" ? canAccess("SETTINGS") || canAccess("CATALOG") : item.id === "staff" ? canAccess("STAFF") || canAccess("USERS") : !requiredPermission[item.id] || canAccess(requiredPermission[item.id]!));
  const activeGroup = nav.some((item) => item.id === tab) ? tab : legacyNav.find((item) => item.id === tab)?.parent ?? "overview";
  const visibleLegacyNav = legacyNav.filter((item) => item.parent === activeGroup && canAccess(item.permission));
  const tabLabel = nav.find((item) => item.id === tab)?.label ?? legacyNav.find((item) => item.id === tab)?.label ?? "Dashboard / Overview";

  const openNewProduct = () => { setEditing(null); setForm(emptyForm(categories[0]?.id)); setImageFile(null); setImagePreview(""); setShowProductForm(true); };
  const openEditProduct = (item: AdminProduct) => {
    const offer = item.offers.find((entry) => entry.source === "AGRI_ONE_STOCK") ?? item.offers[0];
    setEditing(item); setImageFile(null); setImagePreview(item.imageUrl ? `${API_ORIGIN}${item.imageUrl}` : "");
    setForm({ name: item.name, categoryId: item.category.id, brandId: item.brand?.id ?? "", description: item.description ?? "", imageUrl: item.imageUrl ?? "", packSize: item.packSize, unit: item.unit, price: String(offer?.price ?? ""), mrp: String(offer?.mrp ?? offer?.price ?? ""), taxRate: String(item.taxRate ?? 0), sellerSku: offer?.sellerSku ?? `AO-${Date.now().toString().slice(-7)}`, servicePinCodes: (offer?.serviceAreas ?? []).map((area) => area.pinCode).join(", "), minimumOrderQuantity: String(offer?.minimumOrderQuantity ?? 1), stockOnHand: String(offer?.stockOnHand ?? 0), status: item.status });
    setShowProductForm(true);
  };
  const selectImage = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { setError("Image must be smaller than 5 MB"); return; }
    setImageFile(file); setImagePreview(URL.createObjectURL(file));
  };
  const saveProduct = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setError("");
    try {
      let imageUrl = form.imageUrl;
      if (imageFile) {
        const upload = new FormData(); upload.set("image", imageFile);
        const result = await api<{ imageUrl: string }>("/admin/products/image", { method: "POST", body: upload });
        imageUrl = result.imageUrl;
      }
      const body = { ...form, servicePinCodes: [...new Set(form.servicePinCodes.split(",").map((pinCode) => pinCode.trim()).filter(Boolean))], brandId: form.brandId || null, imageUrl, price: Number(form.price), mrp: Number(form.mrp || form.price), taxRate: Number(form.taxRate), minimumOrderQuantity: Number(form.minimumOrderQuantity), stockOnHand: Number(form.stockOnHand) };
      await api(editing ? `/admin/products/${editing.id}` : "/admin/products", { method: editing ? "PATCH" : "POST", body: JSON.stringify(body) });
      setShowProductForm(false); setImageFile(null); showNotice(editing ? "Product updated" : "Product added to catalogue"); await refresh();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not save product"); }
    finally { setBusy(false); }
  };
  const verifyOrganization = (id: string, status: "APPROVED" | "REJECTED" | "NEEDS_CORRECTION") => run(async () => { await api(`/admin/organizations/${id}/verification`, { method: "PATCH", body: JSON.stringify({ status, reason: status === "APPROVED" ? undefined : "Please review the business details and submit corrections." }) }); }, `Business ${status.toLowerCase().replaceAll("_", " ")}`);
  const setAccountStatus = (id: string, status: "ACTIVE" | "DISABLED") => run(async () => { await api(`/admin/users/${id}/status`, { method: "PATCH", body: JSON.stringify({ status }) }); }, `Account ${status.toLowerCase()}`);
  const setStaffStatus = (id: string, status: "ACTIVE" | "DISABLED") => run(async () => { await api(`/admin/staff/${id}/status`, { method: "PATCH", body: JSON.stringify({ status }) }); }, `Staff account ${status.toLowerCase()}`);
  const openAccount = async (id: string) => { setBusy(true); setError(""); try { setAccountDetail(await api<AccountDetail>(`/admin/users/${id}`)); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not load user account details"); } finally { setBusy(false); } };
  const reviewUserDocument = (documentId: string, status: string) => run(async () => { if (!accountDetail?.organization) return; await api(`/admin/organizations/${accountDetail.organization.id}/documents/${documentId}/review`, { method: "PATCH", body: JSON.stringify({ status, reason: status === "APPROVED" ? undefined : "Please submit a clearer or corrected document." }) }); setAccountDetail(await api<AccountDetail>(`/admin/users/${accountDetail.id}`)); }, `Document ${status.toLowerCase().replaceAll("_", " ")}`);
  const reviewUserCertificate = (applicationId: string, status: string) => run(async () => { if (!accountDetail?.organization) return; await api(`/admin/organizations/${accountDetail.organization.id}/certificate-applications/${applicationId}/review`, { method: "PATCH", body: JSON.stringify({ status, reason: status === "APPROVED" ? undefined : "Please contact support for the required corrections." }) }); setAccountDetail(await api<AccountDetail>(`/admin/users/${accountDetail.id}`)); }, `Certificate ${status.toLowerCase().replaceAll("_", " ")}`);
  const downloadUserDocument = async (documentId: string) => { if (!accountDetail?.organization) return; try { const response = await fetch(`${API_BASE}/admin/organizations/${accountDetail.organization.id}/documents/${documentId}/file`, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" }); if (!response.ok) throw new Error(`File request failed (${response.status})`); const url = URL.createObjectURL(await response.blob()); const link = document.createElement("a"); link.href = url; link.download = "compliance-document"; link.click(); URL.revokeObjectURL(url); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not download document"); } };
  const setAdminPermissions = (id: string, permissions: string[]) => run(async () => { await api(`/admin/users/${id}/permissions`, { method: "PATCH", body: JSON.stringify({ permissions }) }); }, "Admin permissions updated");
  const setStaffPermissions = (id: string, permissions: string[]) => run(async () => { await api(`/admin/staff/${id}/permissions`, { method: "PATCH", body: JSON.stringify({ permissions }) }); }, "Staff permissions updated");
  const setOrderStatus = (id: string, status: string) => run(async () => { await api(`/admin/orders/${id}/status`, { method: "PATCH", body: JSON.stringify({ status }) }); }, "Order status updated");
  const reviewOrderReturn = (orderNumber: string, returnId: string, status: string) => run(async () => { await api(`/admin/orders/${encodeURIComponent(orderNumber)}/returns/${returnId}/review`, { method: "PATCH", body: JSON.stringify({ status, reviewReason: status === "REJECTED" ? "Please contact support for return details." : undefined }) }); }, `Return ${status.toLowerCase()}`);
  const setDeliveryStatus = (id: string, status: string, trackingNumber = "") => run(async () => { await api(`/admin/deliveries/${id}/status`, { method: "PATCH", body: JSON.stringify({ status, trackingNumber: trackingNumber || undefined }) }); }, "Delivery status updated");
  const setPaymentStatus = (id: string, status: string) => run(async () => { await api(`/admin/payments/${id}/status`, { method: "PATCH", body: JSON.stringify({ status }) }); }, "Payment status updated");
  const createNotification = (title: string, body: string, audience: string) => run(async () => { await api("/admin/notifications", { method: "POST", body: JSON.stringify({ title, body, audience }) }); }, "Notification published");
  const setNotificationStatus = (id: string, isActive: boolean) => run(async () => { await api(`/admin/notifications/${id}/status`, { method: "PATCH", body: JSON.stringify({ isActive }) }); }, "Notification updated");
  const updateSetting = (key: string, value: Record<string, unknown>) => run(async () => { await api(`/admin/settings/${encodeURIComponent(key)}`, { method: "PUT", body: JSON.stringify({ value }) }); }, "Setting saved");
  const createPromotion = (title: string, body: string, startsAt: string, endsAt: string, type: string, discountPercent: number, minimumOrderQuantity: number, coinsPer100: number) => run(async () => { await api("/admin/promotions", { method: "POST", body: JSON.stringify({ title, body, startsAt: new Date(startsAt).toISOString(), endsAt: new Date(endsAt).toISOString(), type, ...(type !== "REWARDS" ? { discountPercent } : {}), ...(type === "BULK" ? { minimumOrderQuantity } : {}), ...(type === "REWARDS" ? { coinsPer100 } : {}) }) }); }, "Promotion published");
  const setPromotionStatus = (id: string, isActive: boolean) => run(async () => { await api(`/admin/promotions/${id}/status`, { method: "PATCH", body: JSON.stringify({ isActive }) }); }, "Promotion updated");
  const updateSupportTicket = (id: string, status: SupportTicket["status"], adminReply: string) => run(async () => { await api(`/support/admin/tickets/${id}`, { method: "PATCH", body: JSON.stringify({ status, adminReply }) }); }, "Support ticket updated");
  const createPurchaseOrder = (payload: { supplierOrganizationId: string; note: string; lines: { productId: string; quantity: number; unitCost: number }[] }) => run(async () => { await api("/admin/purchases", { method: "POST", body: JSON.stringify(payload) }); }, "Purchase order saved as draft");
  const approvePurchaseOrder = (id: string) => run(async () => { await api(`/admin/purchases/${id}/approve`, { method: "PATCH" }); }, "Purchase order approved");
  const receivePurchaseOrder = (id: string, lines: { lineId: string; quantity: number }[]) => run(async () => { await api(`/admin/purchases/${id}/receive`, { method: "POST", headers: { "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify({ lines }) }); }, "Stock receipt posted");
  const createCashAccount = (payload: { name: string; type: string; bankName?: string; accountNumberLast4?: string; openingBalance: number }) => run(async () => { await api("/admin/finance/accounts", { method: "POST", body: JSON.stringify(payload) }); }, "Cash or bank account created");
  const collectRetailerPayment = (payload: { retailerId: string; orderId: string; accountId: string; amount: number; reference?: string; note?: string }) => run(async () => { await api("/admin/finance/collections", { method: "POST", headers: { "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify(payload) }); }, "Retailer payment recorded");
  const paySupplier = (payload: { purchaseOrderId: string; accountId: string; amount: number; reference?: string; note?: string }) => run(async () => { await api("/admin/finance/supplier-payments", { method: "POST", headers: { "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify(payload) }); }, "Supplier payment recorded");
  const refundRetailerReceipt = (payload: { receiptTransactionId: string; accountId: string; amount: number; reason: string }) => run(async () => { await api("/admin/finance/refunds", { method: "POST", headers: { "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify(payload) }); }, "Retailer refund recorded");
  const postExpense = (payload: { accountId: string; category: string; amount: number; note: string; reference?: string; transactionDate?: string }) => run(async () => { await api("/admin/finance/expenses", { method: "POST", headers: { "Idempotency-Key": crypto.randomUUID() }, body: JSON.stringify(payload) }); }, "Business expense recorded");
  const createStaff = (payload: { name: string; email: string; phone?: string; password: string; role: string; permissions?: string[] }) => run(async () => { await api("/admin/staff", { method: "POST", body: JSON.stringify(payload) }); }, "Staff account created");
  const adjustInventory = (id: string, payload: { quantityDelta: number; reason: string; batchNumber?: string; expiresAt?: string }) => run(async () => { await api(`/admin/inventory/${id}/adjustment`, { method: "POST", body: JSON.stringify(payload) }); }, "Stock adjustment recorded");
  const createDatabaseBackup = () => run(async () => { await api("/admin/backups", { method: "POST" }); }, "Database backup completed");
  const saveOffer = (id: string, payload: Omit<AdminOffer, "id" | "sellerSku" | "source" | "seller" | "reservedQuantity">) => run(async () => { await api(`/admin/offers/${id}`, { method: "PATCH", body: JSON.stringify(payload) }); }, "Seller offer and stock updated");
  const saveMobileHomeTopSelling = (value: { enabled: boolean; title: string; subtitle: string; productIds: string[] }) => run(async () => { await api("/admin/mobile-home/top-selling", { method: "PUT", body: JSON.stringify(value) }); }, "Mobile App Top Selling section updated");
  const archiveProduct = (id: string) => run(async () => { await api(`/admin/products/${id}/archive`, { method: "PATCH" }); }, "Product removed from the public shop");
  const addNamed = (kind: "categories" | "brands", name: string, clear: () => void) => run(async () => { await api(`/admin/${kind}`, { method: "POST", body: JSON.stringify({ name }) }); clear(); }, `${kind === "categories" ? "Category" : "Brand"} added`);
  const saveBrand = (id: string, details: { name: string; description: string; imageUrl: string }, file?: File) => run(async () => {
    let imageUrl = details.imageUrl;
    if (file) { const data = new FormData(); data.set("image", file); const uploaded = await api<{ imageUrl: string }>("/admin/brands/image", { method: "POST", body: data }); imageUrl = uploaded.imageUrl; }
    await api(`/admin/brands/${id}`, { method: "PATCH", body: JSON.stringify({ ...details, imageUrl }) });
  }, "Brand details published to the homepage");
  const setCatalogActive = (kind: "categories" | "brands", id: string, isActive: boolean) => run(async () => { await api(`/admin/${kind}/${id}/status`, { method: "PATCH", body: JSON.stringify({ isActive }) }); }, `${kind === "categories" ? "Category" : "Brand"} ${isActive ? "enabled" : "disabled"}`);
  const selectHomeCardImage = (slug: string, file?: File) => {
    if (!file) return;
    if (!['image/jpeg', 'image/png', 'image/webp', 'image/avif'].includes(file.type) || file.size > 5 * 1024 * 1024) { setError("Choose a JPG, PNG, WebP, or AVIF image under 5 MB"); return; }
    setError("");
    setHomeCardFiles((current) => ({ ...current, [slug]: file }));
    if (homeCardPreviews[slug]) URL.revokeObjectURL(homeCardPreviews[slug]);
    setHomeCardPreviews((current) => ({ ...current, [slug]: URL.createObjectURL(file) }));
  };
  const uploadHomeCardImage = async (slug: string) => {
    const file = homeCardFiles[slug];
    if (!file) return;
    setBusy(true); setError("");
    try {
      const data = new FormData(); data.set("image", file);
      const result = await api<{ slug: string; imageUrl: string }>(`/admin/home-category-cards/${slug}/image`, { method: "POST", body: data });
      setHomeCategoryCards((current) => ({ ...current, [result.slug]: result.imageUrl }));
      setHomeCardFiles((current) => { const next = { ...current }; delete next[slug]; return next; });
      if (homeCardPreviews[slug]) URL.revokeObjectURL(homeCardPreviews[slug]);
      setHomeCardPreviews((current) => { const next = { ...current }; delete next[slug]; return next; });
      showNotice(`${HOME_CARD_SETTINGS.find((item) => item.slug === slug)?.name ?? "Category"} image published on homepage`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not upload category image"); }
    finally { setBusy(false); }
  };

  if (!token) return <div className="admin-auth-screen"><div><span className="admin-auth-icon"><BrandMark className="admin-auth-mark"/></span><h1>Admin sign-in required</h1><p>Sign in with an administrator account to manage the Agri-One marketplace.</p>{error && <p className="admin-error">{error}</p>}<Link className="agri-primary-button" href="/login?next=%2Fadmin">Go to Admin Login</Link></div></div>;

  return <div className="admin-console">
    <aside className="admin-sidebar"><Link href="/" className="admin-brand"><BrandMark className="admin-brand-mark"/><b>Agri-One<small>Platform Admin</small></b></Link><div className="admin-side-label">WORKSPACE</div><nav>{visibleNav.map((item) => <button key={item.id} className={activeGroup === item.id ? "is-active" : ""} onClick={() => { setTab(item.id === "purchases" && !canAccess("PURCHASING") ? "suppliers" : item.id === "products" && !canAccess("CATALOG") ? "inventory" : item.id === "settings" && !canAccess("SETTINGS") ? "catalog" : item.id === "staff" && !canAccess("STAFF") ? "users" : item.id); setSearch(""); }}><span>{item.icon}</span>{item.label}{item.id === "products" && overview.pendingProducts > 0 && <i>{overview.pendingProducts}</i>}</button>)}</nav>{visibleLegacyNav.length > 0 && <div className="admin-subnav" aria-label="Additional modules">{visibleLegacyNav.map((item) => <button key={item.id} className={tab === item.id ? "is-active" : ""} onClick={() => { setTab(item.id); setSearch(""); }}>{item.label}</button>)}</div>}<div className="admin-side-bottom"><span className="admin-avatar">AO</span><div><b>Administrator</b><small>{adminAccess.isSuperAdmin ? "Super admin" : "Scoped admin access"}</small></div><button aria-label="Log out" onClick={() => { window.sessionStorage.removeItem("agri-one-access-token"); setToken(""); router.push("/login"); }}>â†ª</button></div></aside>
    <main className="admin-main"><header className="admin-topbar"><div><span>Admin /</span> {tabLabel}</div><div><span className="admin-live-dot"/> Live backend <button onClick={() => void refresh()}>â†» Refresh</button></div></header><div className="admin-page">
      <div className="admin-page-heading"><div><span className="admin-eyebrow">AGRI-ONE CONTROL CENTER</span><h1>{tab === "overview" ? "Marketplace overview" : tabLabel}</h1><p>{tab === "overview" ? "Manage the entire marketplace from one place." : `Review and manage ${tabLabel.toLowerCase()} across the platform.`}</p></div>{tab === "products" && <button className="admin-primary" onClick={openNewProduct}>ï¼‹ Add Product</button>}</div>
      {error && <div className="admin-error" role="alert">{error}<button onClick={() => setError("")}>Ã—</button></div>}
      {loading && <div className="admin-loading">Loading live marketplace dataâ€¦</div>}
      {!loading && tab === "overview" && <Overview stats={overview} products={products.slice(0, 5)} orders={orders.slice(0, 5)} organizations={organizations.filter((item) => item.verificationStatus === "PENDING").slice(0, 5)} businessDashboard={businessDashboard} onTab={setTab}/>}
      {!loading && tab === "products" && <ProductsPanel products={filteredProducts} search={search} onSearch={setSearch} onEdit={openEditProduct} onNew={openNewProduct} onOfferSave={saveOffer} canManageInventory={canManageInventory} onArchive={archiveProduct}/>}
      {!loading && (tab === "retailers" || tab === "suppliers") && <OrganizationsPanel organizations={filteredOrgs} accounts={accounts.filter((item) => item.role === (tab === "retailers" ? "RETAILER" : "SUPPLIER"))} search={search} onSearch={setSearch} onVerify={verifyOrganization} onAccountStatus={setAccountStatus} onAdminPermissions={setAdminPermissions} canAssignPermissions={adminAccess.isSuperAdmin}/>}
      {!loading && tab === "users" && <AllAccountsPanel accounts={filteredAccounts} search={search} onSearch={setSearch} onAccountStatus={setAccountStatus} onAdminPermissions={setAdminPermissions} canAssignPermissions={adminAccess.isSuperAdmin} onOpenAccount={openAccount}/>}
      {!loading && tab === "orders" && <OrdersPanel orders={filteredOrders} search={search} onSearch={setSearch} onStatus={setOrderStatus} onReturnStatus={reviewOrderReturn}/>}
      {!loading && tab === "purchases" && <PurchasesPanel orders={purchaseOrders} suppliers={organizations.filter((item) => item.type === "SUPPLIER" && item.verificationStatus === "APPROVED")} products={products.filter((item) => item.status === "APPROVED")} busy={busy} onCreate={createPurchaseOrder} onApprove={approvePurchaseOrder} onReceive={receivePurchaseOrder}/>}
      {!loading && tab === "finance" && financeData && <FinancePanel data={financeData} busy={busy} onCreateAccount={createCashAccount} onCollect={collectRetailerPayment} onPaySupplier={paySupplier} onRefund={refundRetailerReceipt} onExpense={postExpense}/>}
      {!loading && tab === "returns" && <ReturnsPanel returns={returnRecords} busy={busy} onReview={reviewOrderReturn}/>}
      {!loading && tab === "staff" && <StaffPanel staff={staff} busy={busy} isSuperAdmin={adminAccess.isSuperAdmin} onCreate={createStaff} onStatus={setStaffStatus} onPermissions={setStaffPermissions}/>}
      {!loading && tab === "activity" && <ActivityPanel events={activity} errors={errorRecords}/>}
      {!loading && tab === "catalog" && <CatalogPanel categories={categories} brands={brands} newCategory={newCategory} newBrand={newBrand} setNewCategory={setNewCategory} setNewBrand={setNewBrand} addNamed={addNamed} setActive={setCatalogActive} onSaveBrand={saveBrand} busy={busy}/>}
      {!loading && tab === "home-cards" && <HomeCardsPanel cards={homeCategoryCards} previews={homeCardPreviews} onSelect={selectHomeCardImage} onSave={uploadHomeCardImage} busy={busy}/>}
      {!loading && tab === "mobile-home" && <MobileHomePanel products={products} settings={settings} busy={busy} onSave={saveMobileHomeTopSelling}/>}
      {!loading && ["inventory", "ledger", "delivery", "offers", "marketing", "reports", "notifications", "settings"].includes(tab) && <OperationsPanel tab={tab === "marketing" ? "offers" : tab} inventory={inventory} deliveries={deliveries} ledger={ledger} reports={reports} businessDashboard={businessDashboard} notifications={notifications} settings={settings} promotions={promotions} products={products} backups={backupRecords} busy={busy} canManageInventory={canManageInventory} onOfferSave={saveOffer} onDeliveryStatus={setDeliveryStatus} onPaymentStatus={setPaymentStatus} onCreateNotification={createNotification} onNotificationStatus={setNotificationStatus} onSettingSave={updateSetting} onCreatePromotion={createPromotion} onPromotionStatus={setPromotionStatus} onStockAdjustment={adjustInventory} onCreateBackup={createDatabaseBackup}/>}
      {accountDetail && <AccountDetailDialog detail={accountDetail} onClose={() => setAccountDetail(null)} onReviewDocument={reviewUserDocument} onReviewCertificate={reviewUserCertificate} onDownloadDocument={downloadUserDocument}/>}
      {showProductForm && <ProductEditor form={form} setForm={setForm} categories={categories} brands={brands} editing={editing} imagePreview={imagePreview} busy={busy} onImage={selectImage} onClose={() => setShowProductForm(false)} onSubmit={saveProduct}/>}
      {!loading && tab === "support" && <SupportTicketsPanel tickets={supportTickets} busy={busy} onUpdate={updateSupportTicket}/>}
      <footer className="admin-footer-note">All changes are saved to the Agri-One backend and recorded for platform operations.</footer>
    </div></main>{notice && <div className="admin-notice" role="status">âœ“ {notice}</div>}</div>;
}

function MobileHomePanel({ products, settings, busy, onSave }: { products: AdminProduct[]; settings: AdminSetting[]; busy: boolean; onSave: (value: { enabled: boolean; title: string; subtitle: string; productIds: string[] }) => void }) {
  const setting = settings.find((item) => item.key === "mobile.home.top-selling");
  const [enabled, setEnabled] = useState(true);
  const [title, setTitle] = useState("ðŸ”¥ Top Selling");
  const [subtitle, setSubtitle] = useState("Most ordered products this week");
  const [productIds, setProductIds] = useState<string[]>([]);
  const [localError, setLocalError] = useState("");
  useEffect(() => {
    const value = setting?.value;
    setEnabled(typeof value?.enabled === "boolean" ? value.enabled : true);
    setTitle(typeof value?.title === "string" ? value.title : "ðŸ”¥ Top Selling");
    setSubtitle(typeof value?.subtitle === "string" ? value.subtitle : "Most ordered products this week");
    setProductIds(Array.isArray(value?.productIds) ? value.productIds.filter((id): id is string => typeof id === "string").slice(0, 9) : []);
  }, [setting]);
  const productById = new Map(products.map((product) => [product.id, product]));
  const candidates = products.filter((product) => product.status === "APPROVED" && product.offers.some((offer) => offer.isActive && offer.stockOnHand - offer.reservedQuantity >= offer.minimumOrderQuantity));
  const toggleProduct = (id: string) => {
    setLocalError("");
    if (productIds.includes(id)) { setProductIds((current) => current.filter((item) => item !== id)); return; }
    if (productIds.length >= 9) { setLocalError("Choose up to nine products for the Top Selling grid."); return; }
    setProductIds((current) => [...current, id]);
  };
  const moveProduct = (index: number, direction: -1 | 1) => setProductIds((current) => {
    const target = index + direction;
    if (target < 0 || target >= current.length) return current;
    const reordered = [...current];
    [reordered[index], reordered[target]] = [reordered[target], reordered[index]];
    return reordered;
  });

  return <section className="admin-panel"><PanelTitle title="Mobile App Â· Top Selling" caption="Configure the mobile home section shown immediately after Recently Bought. Empty product selection uses the live top nine products ordered in the last seven days."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); setLocalError(""); onSave({ enabled, title: title.trim(), subtitle: subtitle.trim(), productIds }); }}>
    <label style={{ display: "flex", alignItems: "center", gap: 10 }}><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)}/> Show this section in the Mobile App</label>
    <label>Section title<input required maxLength={80} value={title} onChange={(event) => setTitle(event.target.value)}/></label>
    <label>Subtitle<input required maxLength={160} value={subtitle} onChange={(event) => setSubtitle(event.target.value)}/></label>
    <div><b>Featured products ({productIds.length}/9)</b><p className="admin-table-sub">Select products to pin them in the chosen order. Leave this empty to rank by order quantities over the previous seven days.</p>
      {productIds.length > 0 && <div className="admin-spaced">{productIds.map((id, index) => <div key={id} className="admin-toolbar" style={{ justifyContent: "space-between", margin: "7px 0", padding: "8px 10px", border: "1px solid #e5ece7", borderRadius: 9 }}><span><b>{index + 1}.</b> {productById.get(id)?.name ?? "Unavailable product"}</span><span><button type="button" className="admin-secondary" disabled={index === 0} onClick={() => moveProduct(index, -1)}>Up</button> <button type="button" className="admin-secondary" disabled={index === productIds.length - 1} onClick={() => moveProduct(index, 1)}>Down</button> <button type="button" className="admin-danger" onClick={() => toggleProduct(id)}>Remove</button></span></div>)}</div>}
      <div className="admin-table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Available offer</th><th>Mobile home</th></tr></thead><tbody>{candidates.map((product) => <tr key={product.id}><td><b>{product.name}</b></td><td>{product.category.name}</td><td>{product.offers.some((offer) => offer.isActive && offer.stockOnHand - offer.reservedQuantity >= offer.minimumOrderQuantity) ? "In stock" : "Unavailable"}</td><td><button type="button" className={productIds.includes(product.id) ? "admin-approve" : "admin-secondary"} onClick={() => toggleProduct(product.id)}>{productIds.includes(product.id) ? "Selected" : "Add"}</button></td></tr>)}</tbody></table>{!candidates.length && <Empty>No approved products with active stock are available to feature.</Empty>}</div>
    </div>
    {localError && <div className="admin-error" role="alert">{localError}</div>}
    <button className="admin-primary" disabled={busy || !title.trim() || !subtitle.trim()}>Save Mobile App Home</button>
  </form></section>;
}

function OperationsPanel({ tab, inventory, deliveries, ledger, reports, businessDashboard, notifications, settings, promotions, products, backups, busy, canManageInventory, onOfferSave, onDeliveryStatus, onPaymentStatus, onCreateNotification, onNotificationStatus, onSettingSave, onCreatePromotion, onPromotionStatus, onStockAdjustment, onCreateBackup }: { tab: string; inventory: InventoryRecord[]; deliveries: DeliveryRecord[]; ledger: LedgerRecord; reports: AdminReports; businessDashboard: BusinessDashboard | null; notifications: AdminNotification[]; settings: AdminSetting[]; promotions: AdminPromotion[]; products: AdminProduct[]; backups: BackupRecord[]; busy: boolean; canManageInventory: boolean; onOfferSave: (id: string, payload: Omit<AdminOffer, "id" | "sellerSku" | "source" | "seller" | "reservedQuantity">) => void; onDeliveryStatus: (id: string, status: string, trackingNumber?: string) => void; onPaymentStatus: (id: string, status: string) => void; onCreateNotification: (title: string, body: string, audience: string) => void; onNotificationStatus: (id: string, active: boolean) => void; onSettingSave: (key: string, value: Record<string, unknown>) => void; onCreatePromotion: (title: string, body: string, startsAt: string, endsAt: string, type: string, discountPercent: number, minimumOrderQuantity: number, coinsPer100: number) => void; onPromotionStatus: (id: string, active: boolean) => void; onStockAdjustment: (id: string, payload: { quantityDelta: number; reason: string; batchNumber?: string; expiresAt?: string }) => void; onCreateBackup: () => void }) {
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [audience, setAudience] = useState("ALL");
  const [settingKey, setSettingKey] = useState("");
  const [settingValue, setSettingValue] = useState("{}");
  const [promotionTitle, setPromotionTitle] = useState("");
  const [promotionBody, setPromotionBody] = useState("");
  const [promotionStart, setPromotionStart] = useState("");
  const [promotionEnd, setPromotionEnd] = useState("");
  const [promotionType, setPromotionType] = useState("FESTIVAL");
  const [discountPercent, setDiscountPercent] = useState("10");
  const [minimumOrderQuantity, setMinimumOrderQuantity] = useState("10");
  const [coinsPer100, setCoinsPer100] = useState("1");
  const [localError, setLocalError] = useState("");
  const [trackingDrafts, setTrackingDrafts] = useState<Record<string, string>>({});
  if (tab === "inventory") return <section className="admin-panel"><PanelTitle title="Shared inventory" caption="Stock, reservations, lot numbers and expiry dates from the shared product offer database."/><div className="admin-table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Seller</th><th>Price</th><th>On hand</th><th>Reserved</th><th>Available</th><th>Update</th></tr></thead><tbody>{inventory.map((row) => <tr key={row.id}><td><b>{row.product.name}</b><small className="admin-table-sub">{row.sellerSku}</small></td><td>{row.product.category.name}</td><td>{row.seller.name}</td><td>{formatRupees(Number(row.price))}</td><td>{row.stockOnHand}</td><td>{row.reservedQuantity}</td><td>{Math.max(0, row.stockOnHand - row.reservedQuantity)}</td><td><details><summary className="admin-secondary">Edit offer</summary><OfferEditor offer={row} onSave={onOfferSave}/></details><StockAdjustmentEditor busy={busy} onSave={(value) => onStockAdjustment(row.id, value)}/></td></tr>)}</tbody></table></div>{inventory.length === 0 && <Empty>No inventory records yet.</Empty>}</section>;
  if (tab === "ledger") return <><section className="admin-panel"><PanelTitle title="Payments" caption="Record collections from Finance & Accounts. Payment states cannot be reversed from this history."/><div className="admin-table-scroll"><table><thead><tr><th>Order</th><th>Retailer</th><th>Provider</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody>{ledger.payments.map((item) => { const statuses = item.status === "PENDING" ? ["PENDING", "AUTHORIZED", "FAILED"] : item.status === "AUTHORIZED" ? ["AUTHORIZED", "FAILED"] : [item.status]; return <tr key={item.id}><td>{item.customerOrder.orderNumber}</td><td>{item.customerOrder.retailer.name}</td><td>{item.provider ?? "Not set"}</td><td>{formatRupees(Number(item.amount))}</td><td><select className="admin-status-select" value={item.status} disabled={busy || statuses.length === 1} onChange={(event) => onPaymentStatus(item.id, event.target.value)}>{statuses.map((status) => <option key={status}>{status}</option>)}</select></td><td>{new Date(item.createdAt).toLocaleDateString()}</td></tr>; })}</tbody></table></div>{ledger.payments.length === 0 && <Empty>No payment records are available.</Empty>}</section><section className="admin-panel admin-spaced"><PanelTitle title="Wallet ledger" caption="Organization credits and debits recorded in the shared database."/><div className="admin-table-scroll"><table><thead><tr><th>Organization</th><th>Type</th><th>Amount</th><th>Description</th><th>Date</th></tr></thead><tbody>{ledger.walletTransactions.map((item) => <tr key={item.id}><td>{item.wallet.organization.name}</td><td>{item.type}</td><td>{formatRupees(Number(item.amount))}</td><td>{item.description}</td><td>{new Date(item.createdAt).toLocaleDateString()}</td></tr>)}</tbody></table></div>{ledger.walletTransactions.length === 0 && <Empty>No wallet transactions are available.</Empty>}</section></>;
  if (tab === "delivery") return <section className="admin-panel"><PanelTitle title="Delivery management" caption="Update parcel progress in order. Delivery completion finalizes stock and COD payment records."/><div className="admin-table-scroll"><table><thead><tr><th>Order</th><th>Recipient</th><th>Destination</th><th>Tracking number</th><th>Status</th><th>Update</th></tr></thead><tbody>{deliveries.map((item) => { const next: Record<string, string[]> = { READY_FOR_PICKUP: ["PICKED_UP"], PICKED_UP: ["IN_TRANSIT", "DELIVERY_FAILED", "RETURNING"], IN_TRANSIT: ["OUT_FOR_DELIVERY", "DELIVERY_FAILED", "RETURNING"], OUT_FOR_DELIVERY: ["DELIVERED", "DELIVERY_FAILED", "RETURNING"], DELIVERY_FAILED: ["OUT_FOR_DELIVERY", "RETURNING"], RETURNING: ["RETURNED"], DELIVERED: [], RETURNED: [] }; const statuses = [item.status, ...(next[item.status] ?? [])]; return <tr key={item.id}><td>{item.fulfillmentOrder.customerOrder.orderNumber}</td><td>{item.fulfillmentOrder.customerOrder.deliveryName}</td><td>{item.fulfillmentOrder.customerOrder.deliveryDistrict} · {item.fulfillmentOrder.customerOrder.deliveryPinCode}</td><td><input aria-label={`Tracking number for ${item.fulfillmentOrder.customerOrder.orderNumber}`} value={trackingDrafts[item.id] ?? item.trackingNumber ?? ""} onChange={(event) => setTrackingDrafts((current) => ({ ...current, [item.id]: event.target.value }))} placeholder="Optional"/></td><td><Status value={item.status}/></td><td><select className="admin-status-select" value={item.status} disabled={busy || statuses.length === 1} onChange={(event) => onDeliveryStatus(item.id, event.target.value, trackingDrafts[item.id] ?? item.trackingNumber ?? "")}>{statuses.map((status) => <option key={status}>{status}</option>)}</select></td></tr>; })}</tbody></table></div>{deliveries.length === 0 && <Empty>Delivery records appear when an order has a shipment.</Empty>}</section>;
  if (tab === "offers") return <><section className="admin-panel"><PanelTitle title="Create promotion" caption="Festival discounts, quantity based bulk deals, or reward points. Campaign rules apply automatically at checkout."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); onCreatePromotion(promotionTitle.trim(), promotionBody.trim(), promotionStart, promotionEnd, promotionType, Number(discountPercent), Number(minimumOrderQuantity), Number(coinsPer100)); setPromotionTitle(""); setPromotionBody(""); }}><label>Promotion title<input required maxLength={160} value={promotionTitle} onChange={(event) => setPromotionTitle(event.target.value)}/></label><label>Offer details<textarea required maxLength={1000} value={promotionBody} onChange={(event) => setPromotionBody(event.target.value)} placeholder="Describe the offer and terms"/></label><label>Scheme type<select value={promotionType} onChange={(event) => setPromotionType(event.target.value)}><option value="FESTIVAL">Festival discount</option><option value="BULK">Bulk discount</option><option value="REWARDS">Reward points</option></select></label>{promotionType !== "REWARDS" && <label>Discount (%)<input required type="number" min="0.01" max="100" step="0.01" value={discountPercent} onChange={(event) => setDiscountPercent(event.target.value)}/></label>}{promotionType === "BULK" && <label>Minimum total quantity<input required type="number" min="1" step="1" value={minimumOrderQuantity} onChange={(event) => setMinimumOrderQuantity(event.target.value)}/></label>}{promotionType === "REWARDS" && <label>Points per â‚¹100 order value<input required type="number" min="1" step="1" value={coinsPer100} onChange={(event) => setCoinsPer100(event.target.value)}/></label>}<div className="admin-form-row"><label>Starts at<input type="datetime-local" required value={promotionStart} onChange={(event) => setPromotionStart(event.target.value)}/></label><label>Ends at<input type="datetime-local" required value={promotionEnd} onChange={(event) => setPromotionEnd(event.target.value)}/></label></div><button className="admin-primary" disabled={busy}>Publish promotion</button></form></section><section className="admin-panel admin-spaced"><PanelTitle title="Promotion campaigns" caption="Live campaigns available in the retailer app."/>{promotions.map((promotion) => <div className="admin-list-row" key={promotion.id}><div><b>{promotion.title} Â· {promotion.type}</b><small>{promotion.type === "REWARDS" ? `${promotion.coinsPer100} points per â‚¹100` : `${promotion.discountPercent ?? 0}% off${promotion.type === "BULK" ? ` Â· min ${promotion.minimumOrderQuantity} items` : ""}`} Â· {promotion.body} Â· {new Date(promotion.startsAt).toLocaleString()} â€“ {new Date(promotion.endsAt).toLocaleString()}</small></div><button className={promotion.isActive ? "admin-danger" : "admin-approve"} disabled={busy} onClick={() => onPromotionStatus(promotion.id, !promotion.isActive)}>{promotion.isActive ? "Deactivate" : "Activate"}</button></div>)}{promotions.length === 0 && <Empty>No promotion campaigns have been created.</Empty>}</section><section className="admin-panel admin-spaced"><PanelTitle title="Product offer pricing" caption="Edit product selling price, MRP, and stock from the shared product records."/><div className="admin-product-list">{products.flatMap((product) => product.offers.map((offer) => <div className="admin-product-management" key={offer.id}><div className="admin-product-row"><ProductThumb image={product.imageUrl} name={product.name}/><div className="admin-product-name"><b>{product.name}</b><small>{offer.seller.name} Â· {offer.source} Â· {offer.isActive ? "Active" : "Inactive"}</small></div><div>{formatRupees(Number(offer.price))}<small>MRP {formatRupees(Number(offer.mrp ?? offer.price))}</small></div></div>{canManageInventory && <OfferEditor offer={offer} onSave={onOfferSave}/>}</div>))}</div></section></>;
  if (tab === "reports") return <ReportsPanel reports={reports} businessDashboard={businessDashboard}/>;
  if (tab === "notifications") return <><section className="admin-panel"><PanelTitle title="Publish notification" caption="Create a platform notice for the selected audience."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); onCreateNotification(title.trim(), body.trim(), audience); setTitle(""); setBody(""); }}><label>Title<input required maxLength={160} value={title} onChange={(event) => setTitle(event.target.value)}/></label><label>Message<textarea required maxLength={2000} value={body} onChange={(event) => setBody(event.target.value)}/></label><label>Audience<select value={audience} onChange={(event) => setAudience(event.target.value)}><option value="ALL">Everyone</option><option value="RETAILERS">Retailers</option><option value="SUPPLIERS">Suppliers</option><option value="OPERATIONS">Operations</option></select></label><button className="admin-primary" disabled={busy}>Publish notification</button></form></section><section className="admin-panel admin-spaced"><PanelTitle title="Notification history" caption="Activate or deactivate published notices."/>{notifications.map((item) => <div className="admin-list-row" key={item.id}><div><b>{item.title}</b><small>{item.audience} Â· {item._count.recipients} recipients Â· {new Date(item.createdAt).toLocaleDateString()}</small></div><button className={item.isActive ? "admin-danger" : "admin-approve"} disabled={busy} onClick={() => onNotificationStatus(item.id, !item.isActive)}>{item.isActive ? "Deactivate" : "Activate"}</button></div>)}{notifications.length === 0 && <Empty>No notifications have been published.</Empty>}</section></>;
  return <><section className="admin-panel"><PanelTitle title="Admin settings" caption="Store platform settings as JSON values in the shared database."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); setLocalError(""); try { const value: unknown = JSON.parse(settingValue); if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Enter a JSON object"); onSettingSave(settingKey.trim(), value as Record<string, unknown>); } catch (cause) { setLocalError(cause instanceof Error ? cause.message : "Invalid JSON"); } }}><label>Setting key<input required maxLength={80} pattern="[A-Za-z0-9._-]+" value={settingKey} onChange={(event) => setSettingKey(event.target.value)} placeholder="store.business-hours"/></label><label>Value (JSON object)<textarea required rows={6} value={settingValue} onChange={(event) => setSettingValue(event.target.value)}/></label>{localError && <div className="admin-error">{localError}</div>}<button className="admin-primary" disabled={busy}>Save setting</button></form><div className="admin-spaced">{settings.map((setting) => <button className="admin-secondary" style={{ margin: 4 }} key={setting.key} onClick={() => { setSettingKey(setting.key); setSettingValue(JSON.stringify(setting.value, null, 2)); }}>{setting.key}</button>)}</div></section><section className="admin-panel admin-spaced"><PanelTitle title="Database backups" caption="Create a private PostgreSQL custom-format backup on the API server. Backup files are not exposed as public uploads."/><button className="admin-primary" disabled={busy} onClick={onCreateBackup}>Create database backup</button><div className="admin-table-scroll" style={{ marginTop: 14 }}><table><thead><tr><th>Created</th><th>Backup file</th><th>Status</th><th>Size</th><th>Created by</th></tr></thead><tbody>{backups.map((backup) => <tr key={backup.id}><td>{new Date(backup.createdAt).toLocaleString()}</td><td>{backup.fileName}<small className="admin-table-sub">{backup.errorCode ?? "Private server storage"}</small></td><td><Status value={backup.status}/></td><td>{backup.sizeBytes === null ? "—" : `${(backup.sizeBytes / 1024 / 1024).toFixed(2)} MB`}</td><td>{backup.actor?.name ?? "System"}</td></tr>)}</tbody></table>{!backups.length && <Empty>No database backups have been created yet.</Empty>}</div></section></>;
}

function Overview({ stats, products, orders, organizations, businessDashboard, onTab }: { stats: Record<string, number>; products: AdminProduct[]; orders: Order[]; organizations: Organization[]; businessDashboard: BusinessDashboard | null; onTab: (tab: Tab) => void }) {
  const cards = [
    { label: "Total users", value: String(stats.users ?? 0), note: "Across marketplace roles", icon: "♙", tone: "green" },
    { label: "Retailers", value: String(stats.retailers ?? 0), note: "Retail business accounts", icon: "▤", tone: "blue" },
    { label: "Suppliers", value: String(stats.suppliers ?? 0), note: "Supplier organizations", icon: "♧", tone: "orange" },
    { label: "Catalogue products", value: String(stats.products ?? 0), note: `${stats.pendingProducts ?? 0} awaiting review`, icon: "▣", tone: "purple" },
    { label: "Total orders", value: String(stats.orders ?? 0), note: "Placed across the platform", icon: "▦", tone: "green" },
    { label: "Live sales", value: formatRupees(stats.revenue ?? 0), note: "Excluding cancelled orders", icon: "₹", tone: "orange" },
    { label: "Pending orders", value: String(businessDashboard?.pendingOrders ?? 0), note: "Waiting for acceptance", icon: "◷", tone: "blue" },
    { label: "Retailer due", value: formatRupees(businessDashboard?.retailerDue ?? 0), note: "Open delivered invoices", icon: "₹", tone: "orange" },
    { label: "Supplier due", value: formatRupees(businessDashboard?.supplierDue ?? 0), note: "Received purchase stock", icon: "₹", tone: "purple" },
    { label: "Low stock", value: String(businessDashboard?.lowStock ?? 0), note: "Active offers at five units or less", icon: "▤", tone: "blue" },
    { label: "Expiring lots", value: String(businessDashboard?.expiringProducts ?? 0), note: "Expiry within 30 days", icon: "⌛", tone: "orange" },
  ];
  const sales = businessDashboard?.monthlySales ?? [];
  const highest = Math.max(1, ...sales.map((row) => row.total));
  return <>
    <div className="admin-stat-grid">{cards.map((card) => <article className={`admin-stat admin-${card.tone}`} key={card.label}><span>{card.icon}</span><div><small>{card.label}</small><strong>{card.value}</strong><em>{card.note}</em></div></article>)}</div>
    <div className="admin-overview-grid">
      <section className="admin-panel admin-wide"><PanelTitle title="Monthly sales" caption="Delivered orders over the last twelve months"/><div className="admin-sales-chart">{sales.length ? sales.map((row) => <div className="admin-sales-month" key={row.month}><div className="admin-sales-bar-wrap" title={`${formatRupees(row.total)} · ${row.orders} orders`}><span style={{ height: `${Math.max(4, row.total / highest * 100)}%` }}/></div><b>{formatRupees(row.total)}</b><small>{new Date(`${row.month}-01T00:00:00`).toLocaleDateString(undefined, { month: "short", year: "2-digit" })}</small></div>) : <Empty>Delivered sales will appear here by month.</Empty>}</div></section>
      <section className="admin-panel"><PanelTitle title="Delivery status" caption="Current shipment progress"/>{businessDashboard?.deliveryStatus.length ? businessDashboard.deliveryStatus.map((item) => <div className="admin-list-row" key={item.status}><Status value={item.status}/><b>{item._count._all}</b></div>) : <Empty>No active delivery records.</Empty>}<h3 className="admin-subheading">Expiry watch</h3>{businessDashboard?.expiringLots.length ? businessDashboard.expiringLots.slice(0, 5).map((lot) => <div className="admin-list-row" key={lot.id}><div><b>{lot.offer.product.name}</b><small>{lot.offer.seller.name} · {lot.batchNumber ?? "No batch"} · {lot.quantity} units</small></div><Status value={lot.expiresAt ? new Date(lot.expiresAt).toLocaleDateString() : "No expiry"}/></div>) : <small className="admin-table-sub">No lots expire in the next 30 days.</small>}<div className="admin-split-actions"><button onClick={() => onTab("orders")}>Review orders</button><button onClick={() => onTab("returns")}>Review claims</button></div></section>
    </div>
    <div className="admin-overview-grid"><section className="admin-panel admin-wide"><PanelTitle title="Recent orders" caption="Latest retailer purchases" action="All orders" onAction={() => onTab("orders")}/>{orders.length ? <div className="admin-table-scroll"><table><thead><tr><th>Order</th><th>Retailer</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id}><td><b>{order.orderNumber}</b></td><td>{order.retailer.name}</td><td>{new Date(order.createdAt).toLocaleDateString()}</td><td>{formatRupees(Number(order.total))}</td><td><Status value={order.status}/></td></tr>)}</tbody></table></div> : <Empty>No orders have been placed yet.</Empty>}</section>
      <section className="admin-panel"><PanelTitle title="Business approvals" caption="Retailers and suppliers" action="Review" onAction={() => onTab("retailers")}/>{organizations.length ? organizations.map((org) => <div className="admin-list-row" key={org.id}><span className="admin-row-avatar">{org.name.slice(0, 1)}</span><div><b>{org.name}</b><small>{org.type.toLowerCase()} · {org._count.users} account(s)</small></div><Status value={org.verificationStatus}/></div>) : <Empty>No pending business reviews.</Empty>}</section>
    </div>
    <div className="admin-overview-grid"><section className="admin-panel"><PanelTitle title="Product catalogue" caption="Recently updated products" action="Manage products" onAction={() => onTab("products")}/>{products.length ? products.map((product) => <div className="admin-list-row" key={product.id}><ProductThumb image={product.imageUrl} name={product.name}/><div><b>{product.name}</b><small>{product.category.name} · {product.brand?.name ?? "No brand"}</small></div><Status value={product.status}/></div>) : <Empty>No products are in the catalogue.</Empty>}</section><section className="admin-panel admin-quick-panel"><PanelTitle title="Quick controls" caption="Common platform tasks"/><button onClick={() => onTab("products")}>＋ Add or update products <b>→</b></button><button onClick={() => onTab("retailers")}>♙ Verify retailer accounts <b>→</b></button><button onClick={() => onTab("purchases")}>⇅ Create supplier purchase <b>→</b></button><button onClick={() => onTab("finance")}>₹ Collect payment or record expense <b>→</b></button><button onClick={() => onTab("settings")}>⚙ Configure catalogue and mobile home <b>→</b></button></section></div>
  </>;
}
function HomeCardsPanel({ cards, previews, onSelect, onSave, busy }: { cards: Record<string, string>; previews: Record<string, string>; onSelect: (slug: string, file?: File) => void; onSave: (slug: string) => void; busy: boolean }) {
  return <section className="admin-panel admin-home-cards-panel"><PanelTitle title="Homepage category images" caption="Upload your own image for each of the four category cards. Publishing updates the public homepage right away."/><div className="admin-home-card-grid">{HOME_CARD_SETTINGS.map((card) => {
    const imageUrl = cards[card.slug] ? `${API_ORIGIN}${cards[card.slug]}` : card.defaultImage;
    const preview = previews[card.slug] ?? imageUrl;
    return <article className="admin-home-card-editor" key={card.slug}><div className="admin-home-card-preview">{preview ? <Image src={preview} alt={`${card.name} category card preview`} fill unoptimized/> : <span aria-hidden="true">ðŸšœ</span>}</div><div className="admin-home-card-copy"><div><h3>{card.name}</h3><p>{previews[card.slug] ? "New image ready to publish" : cards[card.slug] ? "Custom homepage image" : "Current default image"}</p></div><label className="admin-home-card-picker">Choose image<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => onSelect(card.slug, event.currentTarget.files?.[0])}/></label><button className="admin-primary" type="button" disabled={busy || !previews[card.slug]} onClick={() => onSave(card.slug)}>{busy ? "Uploadingâ€¦" : "Upload & publish"}</button><small>JPG, PNG, WebP, or AVIF Â· max 5 MB</small></div></article>;
  })}</div></section>;
}

function ProductsPanel({ products, search, onSearch, onEdit, onNew, onOfferSave, canManageInventory, onArchive }: { products: AdminProduct[]; search: string; onSearch: (value: string) => void; onEdit: (product: AdminProduct) => void; onNew: () => void; onOfferSave: (id: string, payload: Omit<AdminOffer, "id" | "sellerSku" | "source" | "seller" | "reservedQuantity">) => void; canManageInventory: boolean; onArchive: (id: string) => void }) {
  return <section className="admin-panel"><div className="admin-toolbar"><label>? <input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search products, brands, status?"/></label><span>{products.length} products</span><button className="admin-primary" onClick={onNew}>+ Add Product</button></div><div className="admin-product-list">{products.map((product) => { const offer = product.offers.find((entry) => entry.source === "AGRI_ONE_STOCK") ?? product.offers[0]; return <div className="admin-product-management" key={product.id}><article className="admin-product-row"><ProductThumb image={product.imageUrl} name={product.name}/><div className="admin-product-name"><b>{product.name}</b><small>{product.brand?.name ?? "No brand"} ? {product.category.name} ? {product.packSize} {product.unit}</small><small>{product.offers.length} offer(s) ? SKU {offer?.sellerSku ?? "?"}</small></div><div><b>{offer ? formatRupees(Number(offer.price)) : "No offer"}</b><small>Stock {offer?.stockOnHand ?? 0} ? {offer?.seller.name ?? "?"}</small></div><Status value={product.status}/><div className="admin-product-controls"><button className="admin-secondary" onClick={() => onEdit(product)}>Edit details</button><button className="admin-danger" disabled={product.status === "ARCHIVED"} onClick={() => onArchive(product.id)}>{product.status === "ARCHIVED" ? "Removed" : "Remove from shop"}</button></div></article>{canManageInventory && product.offers.length > 0 && <details className="admin-offer-details"><summary>Manage supplier offers and inventory ({product.offers.length})</summary><div>{product.offers.map((item) => <OfferEditor key={item.id} offer={item} onSave={onOfferSave}/>)}</div></details>}</div>; })}{!products.length && <Empty>No matching products. Add a product to start the catalogue.</Empty>}</div></section>;
}

type OfferEditRecord = Pick<AdminOffer, "id" | "price" | "mrp" | "minimumOrderQuantity" | "stockOnHand" | "commissionRate" | "isActive" | "reservedQuantity" | "sellerSku" | "source"> & { seller: { name: string } };

function OfferEditor({ offer, onSave }: { offer: OfferEditRecord; onSave: (id: string, payload: Omit<AdminOffer, "id" | "sellerSku" | "source" | "seller" | "reservedQuantity">) => void }) {
  const [price, setPrice] = useState(String(offer.price)); const [mrp, setMrp] = useState(String(offer.mrp ?? offer.price)); const [minimumOrderQuantity, setMinimumOrderQuantity] = useState(String(offer.minimumOrderQuantity)); const [stockOnHand, setStockOnHand] = useState(String(offer.stockOnHand)); const [commissionRate, setCommissionRate] = useState(String(offer.commissionRate)); const [isActive, setIsActive] = useState(offer.isActive);
  return <form className="admin-offer-row" onSubmit={(event) => { event.preventDefault(); onSave(offer.id, { price: Number(price), mrp: Number(mrp), minimumOrderQuantity: Number(minimumOrderQuantity), stockOnHand: Number(stockOnHand), commissionRate: Number(commissionRate), isActive }); }}><span><b>{offer.seller.name}</b><small>{offer.source.replaceAll("_", " ")} Â· {offer.sellerSku} Â· {offer.reservedQuantity} reserved</small></span><label>Price<input type="number" min="0" step="0.01" value={price} onChange={(event) => setPrice(event.target.value)}/></label><label>MRP<input type="number" min="0" step="0.01" value={mrp} onChange={(event) => setMrp(event.target.value)}/></label><label>MOQ<input type="number" min="1" value={minimumOrderQuantity} onChange={(event) => setMinimumOrderQuantity(event.target.value)}/></label><label>Stock<input type="number" min={offer.reservedQuantity} value={stockOnHand} onChange={(event) => setStockOnHand(event.target.value)}/></label><label>Commission %<input type="number" min="0" max="100" step="0.01" value={commissionRate} onChange={(event) => setCommissionRate(event.target.value)}/></label><label className="admin-offer-active"><input type="checkbox" checked={isActive} onChange={(event) => setIsActive(event.target.checked)}/> Active</label><button className="admin-secondary">Save</button></form>;
}

function OrganizationsPanel({ organizations, accounts, search, onSearch, onVerify, onAccountStatus, onAdminPermissions, canAssignPermissions }: { organizations: Organization[]; accounts: Account[]; search: string; onSearch: (value: string) => void; onVerify: (id: string, status: "APPROVED" | "REJECTED" | "NEEDS_CORRECTION") => void; onAccountStatus: (id: string, status: "ACTIVE" | "DISABLED") => void; onAdminPermissions: (id: string, permissions: string[]) => void; canAssignPermissions: boolean }) {
  return <><section className="admin-panel"><PanelTitle title="Business verification" caption="Review organization details and approve marketplace access"/><div className="admin-toolbar"><label>âŒ• <input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search business or emailâ€¦"/></label><span>{organizations.length} businesses</span></div><div className="admin-table-scroll"><table><thead><tr><th>Business</th><th>Contact</th><th>Accounts</th><th>Verification</th><th>Actions</th></tr></thead><tbody>{organizations.map((org) => <tr key={org.id}><td><b>{org.name}</b><small className="admin-table-sub">{org.type}</small></td><td>{org.email ?? "â€”"}<small className="admin-table-sub">{org.phone ?? ""}</small></td><td>{org._count.users}</td><td><Status value={org.verificationStatus}/>{org.verificationReason && <small className="admin-table-sub">{org.verificationReason}</small>}</td><td><div className="admin-actions"><button className="admin-approve" onClick={() => onVerify(org.id, "APPROVED")}>Approve</button>{org.verificationStatus !== "NEEDS_CORRECTION" && <button className="admin-secondary" onClick={() => onVerify(org.id, "NEEDS_CORRECTION")}>Request edits</button>}{org.verificationStatus !== "REJECTED" && <button className="admin-danger" onClick={() => onVerify(org.id, "REJECTED")}>Reject</button>}</div></td></tr>)}</tbody></table>{!organizations.length && <Empty>No businesses match this search.</Empty>}</div></section><section className="admin-panel admin-spaced"><PanelTitle title="Platform accounts" caption="Enable or disable sign-in for retailer or supplier accounts"/><div className="admin-table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Business</th><th>Account</th><th>Access</th></tr></thead><tbody>{accounts.map((account) => <tr key={account.id}><td><b>{account.name}</b></td><td>{account.email}</td><td>{account.organization?.name ?? "â€”"}</td><td><Status value={account.status}/></td><td><button className={account.status === "ACTIVE" ? "admin-danger" : "admin-approve"} onClick={() => onAccountStatus(account.id, account.status === "ACTIVE" ? "DISABLED" : "ACTIVE")}>{account.status === "ACTIVE" ? "Disable" : "Enable"}</button>{account.role === "ADMIN" && canAssignPermissions && <button className="admin-secondary" onClick={() => { const input = window.prompt("Enter admin permissions separated by commas (CATALOG, RETAILERS, ORDERS, INVENTORY, FINANCE, DELIVERY, REPORTS, NOTIFICATIONS, SETTINGS, USERS, PURCHASING, STAFF, ACTIVITY)", (account.adminPermissions ?? []).join(",")); if (input !== null) onAdminPermissions(account.id, input.split(",").map((permission) => permission.trim().toUpperCase()).filter(Boolean)); }}>Permissions</button>}</td></tr>)}</tbody></table>{!accounts.length && <Empty>No platform user accounts found.</Empty>}</div></section></>;
}

function OrdersPanel({ orders, search, onSearch, onStatus, onReturnStatus }: { orders: Order[]; search: string; onSearch: (value: string) => void; onStatus: (id: string, status: string) => void; onReturnStatus: (orderNumber: string, returnId: string, status: string) => void }) {
  const statuses = ["PLACED", "PARTIALLY_ACCEPTED", "ACCEPTED", "PARTIALLY_DISPATCHED", "DISPATCHED", "DELIVERED", "PARTIALLY_CANCELLED", "CANCELLED", "REJECTED"];
  return <section className="admin-panel"><div className="admin-toolbar"><label>âŒ• <input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search order number or retailerâ€¦"/></label><span>{orders.length} orders</span></div><div className="admin-table-scroll"><table><thead><tr><th>Order</th><th>Retailer</th><th>Fulfillment</th><th>Delivery</th><th>Total / COD</th><th>Status</th><th>Returns</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id}><td><b>{order.orderNumber}</b><small className="admin-table-sub">{new Date(order.createdAt).toLocaleDateString()}</small></td><td>{order.retailer.name}</td><td>{order.fulfillments.flatMap((item) => item.lines).reduce((count, line) => count + line.quantity, 0)} items Â· {order.fulfillments.length} supplier(s)</td><td>{order.deliveryName}<small className="admin-table-sub">{order.deliveryDistrict}</small></td><td><b>{formatRupees(Number(order.total))}</b><small className="admin-table-sub">{order.paymentMethod ?? "Payment unspecified"} Â· {order.payments?.[0]?.status ?? "â€”"}</small></td><td><select className="admin-status-select" value={order.status} disabled={order.status !== "PLACED" && order.status !== "PARTIALLY_ACCEPTED"} onChange={(event) => onStatus(order.id, event.target.value)}>{[order.status, ...(order.status === "PLACED" || order.status === "PARTIALLY_ACCEPTED" ? ["ACCEPTED", "CANCELLED", "REJECTED"] : [])].map((status) => <option key={status}>{status}</option>)}</select></td><td>{order.returnRequests?.map((request) => <div key={request.id} style={{ minWidth: 170, marginBottom: 7 }}><b>{request.status}</b><small className="admin-table-sub">{request.reason}</small>{["REQUESTED", "APPROVED"].includes(request.status) && <div className="admin-actions">{request.status === "REQUESTED" && <><button className="admin-approve" onClick={() => onReturnStatus(order.orderNumber, request.id, "APPROVED")}>Approve</button><button className="admin-danger" onClick={() => onReturnStatus(order.orderNumber, request.id, "REJECTED")}>Reject</button></>}{request.status === "APPROVED" && <button className="admin-approve" onClick={() => onReturnStatus(order.orderNumber, request.id, "COMPLETED")}>Complete return</button>}</div>}</div>) ?? "â€”"}</td></tr>)}</tbody></table>{!orders.length && <Empty>No orders match this search.</Empty>}</div></section>;
}

function AllAccountsPanel({ accounts, search, onSearch, onAccountStatus, onAdminPermissions, canAssignPermissions, onOpenAccount }: { accounts: Account[]; search: string; onSearch: (value: string) => void; onAccountStatus: (id: string, status: "ACTIVE" | "DISABLED") => void; onAdminPermissions: (id: string, permissions: string[]) => void; canAssignPermissions: boolean; onOpenAccount: (id: string) => void }) {
  return <section className="admin-panel"><PanelTitle title="All platform accounts" caption="Search and control every user sign-in across retailer, supplier and operations roles"/><div className="admin-toolbar"><label>âŒ• <input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search name, email, role, businessâ€¦"/></label><span>{accounts.length} accounts loaded</span></div><div className="admin-table-scroll"><table><thead><tr><th>User</th><th>Role</th><th>Business</th><th>Joined</th><th>Account</th><th>Access</th></tr></thead><tbody>{accounts.map((account) => <tr key={account.id}><td><b>{account.name}</b><small className="admin-table-sub">{account.email}{account.phone ? ` Â· ${account.phone}` : ""}</small></td><td>{account.role}</td><td>{account.organization?.name ?? "â€”"}</td><td>{new Date(account.createdAt).toLocaleDateString()}</td><td><Status value={account.status}/></td><td><button className="admin-secondary" onClick={() => onOpenAccount(account.id)}>View account</button> <button className={account.status === "ACTIVE" ? "admin-danger" : "admin-approve"} onClick={() => onAccountStatus(account.id, account.status === "ACTIVE" ? "DISABLED" : "ACTIVE")}>{account.status === "ACTIVE" ? "Disable" : "Enable"}</button>{account.role === "ADMIN" && <button className="admin-secondary" onClick={() => { const input = window.prompt("Enter admin permissions separated by commas (CATALOG, RETAILERS, ORDERS, INVENTORY, FINANCE, DELIVERY, REPORTS, NOTIFICATIONS, SETTINGS, USERS, PURCHASING, STAFF, ACTIVITY)", (account.adminPermissions ?? []).join(",")); if (input !== null) onAdminPermissions(account.id, input.split(",").map((permission) => permission.trim().toUpperCase()).filter(Boolean)); }}>Permissions</button>}</td></tr>)}</tbody></table>{!accounts.length && <Empty>No user accounts match this search.</Empty>}</div></section>;
}

function ReportsPanel({ reports, businessDashboard }: { reports: AdminReports; businessDashboard: BusinessDashboard | null }) {
  const sales = businessDashboard?.monthlySales ?? [];
  const highestMonth = Math.max(1, ...sales.map((row) => row.total));
  const metrics = [
    ["Delivered sales", formatRupees(reports.orderValues.revenue)],
    ["Delivered orders", String(reports.orderValues.count)],
    ["Retailer due", formatRupees(businessDashboard?.retailerDue ?? 0)],
    ["Supplier due", formatRupees(businessDashboard?.supplierDue ?? 0)],
    ["Cash & bank", formatRupees(businessDashboard?.cashAndBank ?? 0)],
    ["Low stock offers", String(reports.inventory.lowStockOffers)],
  ];
  return <>
    <div className="admin-stat-grid">{metrics.map(([label, value]) => <article className="admin-stat admin-green" key={label}><span>₹</span><div><small>{label}</small><strong>{value}</strong><em>Live database totals</em></div></article>)}</div>
    <section className="admin-panel admin-spaced"><PanelTitle title="Monthly sales trend" caption="Completed deliveries with completed returns excluded"/><div className="admin-sales-chart">{sales.length ? sales.map((row) => <div className="admin-sales-month" key={row.month}><div className="admin-sales-bar-wrap" title={`${formatRupees(row.total)} · ${row.orders} orders`}><span style={{ height: `${Math.max(4, row.total / highestMonth * 100)}%` }}/></div><b>{formatRupees(row.total)}</b><small>{new Date(`${row.month}-01T00:00:00`).toLocaleDateString(undefined, { month: "short", year: "2-digit" })}</small></div>) : <Empty>Delivered sales will appear here by month.</Empty>}</div></section>
    <div className="admin-overview-grid">
      <ReportBreakdown title="Orders by status" rows={reports.orders.map((row) => ({ label: row.status, value: row._count._all }))}/>
      <ReportBreakdown title="Products by status" rows={reports.products.map((row) => ({ label: row.status, value: row._count._all }))}/>
      <ReportBreakdown title="Payments by status" rows={reports.paymentTotals.map((row) => ({ label: row.status, value: row._count._all, detail: formatRupees(Number(row._sum.amount ?? 0)) }))}/>
      <ReportBreakdown title="Platform users by role" rows={reports.users.map((row) => ({ label: row.role, value: row._count._all }))}/>
      <section className="admin-panel"><PanelTitle title="Inventory summary" caption="Shared offers and available units"/><div className="admin-list-row"><b>Stock on hand</b><strong>{reports.inventory.unitsOnHand.toLocaleString()}</strong></div><div className="admin-list-row"><b>Product offers</b><strong>{reports.inventory.offers.toLocaleString()}</strong></div><div className="admin-list-row"><b>Low stock offers</b><strong>{reports.inventory.lowStockOffers.toLocaleString()}</strong></div></section>
      <section className="admin-panel"><PanelTitle title="Cash flow summary" caption="Recorded financial transactions to date"/><div className="admin-list-row"><b>Collections</b><strong>{formatRupees(businessDashboard?.collections ?? 0)}</strong></div><div className="admin-list-row"><b>Business expenses</b><strong>{formatRupees(businessDashboard?.expenses ?? 0)}</strong></div><div className="admin-list-row"><b>Cash and bank balance</b><strong>{formatRupees(businessDashboard?.cashAndBank ?? 0)}</strong></div></section>
    </div>
  </>;
}

function ReportBreakdown({ title, rows }: { title: string; rows: { label: string; value: number; detail?: string }[] }) {
  const highest = Math.max(1, ...rows.map((row) => row.value));
  return <section className="admin-panel"><PanelTitle title={title} caption="Current totals"/>{rows.length ? <div className="admin-report-rows">{rows.map((row) => <div className="admin-report-row" key={row.label}><div><b>{row.label.replaceAll("_", " ")}</b><span>{row.detail ?? row.value.toLocaleString()}</span></div><div className="admin-report-track"><span style={{ width: `${Math.max(3, row.value / highest * 100)}%` }}/></div></div>)}</div> : <Empty>No records to report.</Empty>}</section>;
}

function AccountDetailDialog({ detail, onClose, onReviewDocument, onReviewCertificate, onDownloadDocument }: { detail: AccountDetail; onClose: () => void; onReviewDocument: (id: string, status: string) => void; onReviewCertificate: (id: string, status: string) => void; onDownloadDocument: (id: string) => void }) {
  const org = detail.organization;
  return <div role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }} style={{ position: "fixed", inset: 0, zIndex: 100, display: "grid", placeItems: "center", padding: 16, background: "rgba(15,24,18,.55)" }}><section role="dialog" aria-modal="true" aria-label={`${detail.name} account details`} style={{ width: "min(920px, 100%)", maxHeight: "90vh", overflow: "auto", padding: 22, borderRadius: 16, background: "#fff", color: "#17231c" }}>
    <header style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 16 }}><div><h2 style={{ margin: 0 }}>{detail.name}</h2><p style={{ margin: "6px 0", color: "#66736b" }}>{detail.email} Â· {detail.role} Â· {detail.status}</p><p style={{ margin: 0, color: "#66736b" }}>{org?.name ?? "No business linked"} {org ? `Â· ${org.verificationStatus}` : ""}</p></div><button className="admin-secondary" onClick={onClose}>Close</button></header>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(250px,1fr))", gap: 14, marginTop: 18 }}>
      <AccountDetailSection title="Account"><DetailLine label="Phone" value={detail.phone}/><DetailLine label="Email verified" value={detail.emailVerifiedAt ? new Date(detail.emailVerifiedAt).toLocaleString() : "No"}/><DetailLine label="Phone verified" value={detail.phoneVerifiedAt ? new Date(detail.phoneVerifiedAt).toLocaleString() : "No"}/><DetailLine label="Created" value={new Date(detail.createdAt).toLocaleString()}/></AccountDetailSection>
      <AccountDetailSection title="Shop details"><DetailLine label="Entity" value={org?.businessEntityType}/><DetailLine label="GSTIN" value={org?.gstin}/><DetailLine label="PIN / City" value={[org?.shopPinCode, org?.shopCity].filter(Boolean).join(" Â· ")}/><DetailLine label="District / State" value={[org?.shopDistrict, org?.shopState].filter(Boolean).join(" Â· ")}/><DetailLine label="Address" value={[org?.shopNumber, org?.shopArea, org?.shopLandmark].filter(Boolean).join(", ")}/><DetailLine label="Review note" value={org?.verificationReason}/></AccountDetailSection>
      <AccountDetailSection title="Money & ledger"><DetailLine label="Balance" value={org?.wallet ? formatRupees(Number(org.wallet.balance)) : "No wallet"}/><DetailLine label="Coins" value={org?.wallet?.coinBalance}/>{org?.wallet?.transactions.slice(0, 12).map((item) => <DetailLine key={item.id} label={`${item.type} Â· ${new Date(item.createdAt).toLocaleDateString()}`} value={`${formatRupees(Number(item.amount))} Â· ${item.description}`}/>)}</AccountDetailSection>
      <AccountDetailSection title="Delivery addresses">{org?.deliveryAddresses.length ? org.deliveryAddresses.map((item) => <DetailLine key={item.id} label={`${item.label}${item.isDefault ? " Â· Default" : ""}`} value={`${item.recipientName} Â· ${item.phone} Â· ${item.address}, ${item.area}, ${item.district} ${item.pinCode}`}/>) : <DetailLine label="Addresses" value="None saved"/>}</AccountDetailSection>
      <AccountDetailSection title="Supporting ID & license">{org?.kycDocuments.length ? org.kycDocuments.map((doc) => <div key={doc.id} style={{ padding: "8px 0", borderBottom: "1px solid #edf0ed" }}><b>{doc.documentType} Â· {doc.reviewStatus}</b><div style={{ color: "#66736b", fontSize: 12 }}>{doc.originalName}{doc.reviewReason ? ` Â· ${doc.reviewReason}` : ""}</div><button className="admin-secondary" onClick={() => onDownloadDocument(doc.id)}>Download file</button>{doc.reviewStatus !== "APPROVED" && <><button className="admin-approve" onClick={() => onReviewDocument(doc.id, "APPROVED")}>Approve</button><button className="admin-danger" onClick={() => onReviewDocument(doc.id, "NEEDS_CORRECTION")}>Request correction</button></>}</div>) : <DetailLine label="Documents" value="None submitted"/>}</AccountDetailSection>
      <AccountDetailSection title="Principal certificates">{org?.certificateApplications.length ? org.certificateApplications.map((item) => <div key={item.id} style={{ padding: "8px 0", borderBottom: "1px solid #edf0ed" }}><b>{item.certificate} Â· {item.status}</b><div style={{ color: "#66736b", fontSize: 12 }}>{item.purpose || "No purpose provided"}{item.reviewReason ? ` Â· ${item.reviewReason}` : ""}</div>{item.status === "PENDING" && <><button className="admin-approve" onClick={() => onReviewCertificate(item.id, "APPROVED")}>Approve</button><button className="admin-danger" onClick={() => onReviewCertificate(item.id, "NEEDS_CORRECTION")}>Request correction</button></>}</div>) : <DetailLine label="Applications" value="None"/>}</AccountDetailSection>
    </div>
    <AccountDetailSection title={`My orders (${org?.retailerOrders.length ?? 0} latest)`}>{org?.retailerOrders.length ? org.retailerOrders.map((order) => <DetailLine key={order.id} label={`${order.orderNumber} Â· ${order.status} Â· ${new Date(order.createdAt).toLocaleDateString()}`} value={`${formatRupees(Number(order.total))} Â· ${order.fulfillments.flatMap((f) => f.lines).map((line) => `${line.productNameSnapshot} Ã—${line.quantity}`).join(", ")}${order.returnRequests.length ? ` Â· Returns: ${order.returnRequests.map((r) => r.status).join(", ")}` : ""}`}/>) : <DetailLine label="Orders" value="None"/>}</AccountDetailSection>
  </section></div>;
}
function AccountDetailSection({ title, children }: { title: string; children: ReactNode }) { return <section style={{ marginTop: 14, padding: 14, border: "1px solid #e5eae6", borderRadius: 12 }}><h3 style={{ margin: "0 0 8px", fontSize: 15 }}>{title}</h3>{children}</section>; }
function DetailLine({ label, value }: { label: string; value: unknown }) { return <div style={{ display: "flex", justifyContent: "space-between", gap: 12, padding: "5px 0", borderBottom: "1px solid #edf0ed", fontSize: 12 }}><b>{label}</b><span style={{ textAlign: "right", overflowWrap: "anywhere", color: "#526157" }}>{value === null || value === undefined || value === "" ? "â€”" : String(value)}</span></div>; }

function CatalogPanel({ categories, brands, newCategory, newBrand, setNewCategory, setNewBrand, addNamed, setActive, onSaveBrand, busy }: { categories: Named[]; brands: Named[]; newCategory: string; newBrand: string; setNewCategory: (value: string) => void; setNewBrand: (value: string) => void; addNamed: (kind: "categories" | "brands", name: string, clear: () => void) => void; setActive: (kind: "categories" | "brands", id: string, active: boolean) => void; onSaveBrand: (id: string, details: { name: string; description: string; imageUrl: string }, file?: File) => void; busy: boolean }) {
  return <div className="admin-catalog-layout"><section className="admin-panel"><PanelTitle title="Categories" caption="Manage the catalogue groups"/><form className="admin-add-inline" onSubmit={(event) => { event.preventDefault(); if (newCategory.trim()) addNamed("categories", newCategory.trim(), () => setNewCategory("")); }}><input value={newCategory} onChange={(event) => setNewCategory(event.target.value)} placeholder="New category name"/><button className="admin-primary">+ Add</button></form>{categories.map((item) => <div className="admin-catalog-row" key={item.id}><span>?</span><b>{item.name}</b><small>{item._count?.products ?? 0} products</small><button className="admin-catalog-toggle" onClick={() => setActive("categories", item.id, !item.isActive)}>{item.isActive ? "Disable" : "Enable"}</button></div>)}</section><section className="admin-panel admin-brand-management"><PanelTitle title="Brand identity" caption="Upload a logo, edit the brand name and add a short description. Saved changes appear on the public homepage."/><form className="admin-add-inline" onSubmit={(event) => { event.preventDefault(); if (newBrand.trim()) addNamed("brands", newBrand.trim(), () => setNewBrand("")); }}><input value={newBrand} onChange={(event) => setNewBrand(event.target.value)} placeholder="Add a new brand name"/><button className="admin-primary">+ Add brand</button></form>{brands.length ? <div className="admin-brand-editor-list">{brands.map((brand) => <BrandEditor key={brand.id + "-" + brand.name + "-" + (brand.imageUrl ?? "") + "-" + (brand.description ?? "")} brand={brand} busy={busy} onSave={onSaveBrand}/>)}</div> : <Empty>Add a brand to create its homepage card.</Empty>}</section></div>;
}

function BrandEditor({ brand, busy, onSave }: { brand: Named; busy: boolean; onSave: (id: string, details: { name: string; description: string; imageUrl: string }, file?: File) => void }) {
  const [name, setName] = useState(brand.name);
  const [description, setDescription] = useState(brand.description ?? "");
  const [file, setFile] = useState<File>();
  const [preview, setPreview] = useState("");
  const [error, setError] = useState("");
  const imageUrl = preview || (brand.imageUrl ? (brand.imageUrl.startsWith("http") ? brand.imageUrl : API_ORIGIN + brand.imageUrl) : "");
  return <form className="admin-brand-editor" onSubmit={(event) => { event.preventDefault(); onSave(brand.id, { name: name.trim(), description: description.trim(), imageUrl: brand.imageUrl ?? "" }, file); }}><div className="admin-brand-editor-image">{imageUrl ? <Image src={imageUrl} alt={name + " logo preview"} width={88} height={88} unoptimized/> : <b>{name.slice(0, 1).toUpperCase()}</b>}</div><div className="admin-brand-editor-fields"><div className="admin-brand-editor-row"><label>Brand name<input required maxLength={100} value={name} onChange={(event) => setName(event.target.value)}/></label><label>Brand description<input maxLength={500} value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Short description for shoppers"/></label></div><div className="admin-brand-editor-actions"><label className="admin-home-card-picker">{file ? "Change selected logo" : "Choose logo image"}<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => { const selected = event.currentTarget.files?.[0]; if (!selected) return; if (!["image/jpeg", "image/png", "image/webp", "image/avif"].includes(selected.type) || selected.size > 5 * 1024 * 1024) { setError("Choose a JPG, PNG, WebP, or AVIF image under 5 MB"); return; } setError(""); setFile(selected); setPreview(URL.createObjectURL(selected)); }}/></label><button className="admin-primary" disabled={busy}>{busy ? "Saving..." : "Save brand"}</button><small>{file?.name ?? "JPG, PNG, WebP, or AVIF ? max 5 MB"}</small></div>{error && <small className="admin-brand-error">{error}</small>}</div></form>;
}

function ProductEditor({ form, setForm, categories, brands, editing, imagePreview, busy, onImage, onClose, onSubmit }: { form: ProductForm; setForm: (value: ProductForm) => void; categories: Named[]; brands: Named[]; editing: AdminProduct | null; imagePreview: string; busy: boolean; onImage: (event: ChangeEvent<HTMLInputElement>) => void; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) {
  const change = (key: keyof ProductForm, value: string) => setForm({ ...form, [key]: value });
  return <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="admin-product-modal" role="dialog" aria-modal="true" aria-labelledby="admin-product-title"><header><div><span className="admin-eyebrow">CATALOGUE MANAGEMENT</span><h2 id="admin-product-title">{editing ? "Edit product" : "Add product"}</h2></div><button onClick={onClose} aria-label="Close">Ã—</button></header><form onSubmit={onSubmit}><div className="admin-form-layout"><div className="admin-image-upload"><div>{imagePreview ? <Image src={imagePreview} alt="Product preview" fill unoptimized/> : <span>â–§</span>}</div><label className="admin-secondary">Upload product image<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={onImage}/></label><small>JPG, PNG, WebP or AVIF Â· max 5 MB</small></div><div className="admin-form-fields"><label>Product name<input required maxLength={160} value={form.name} onChange={(event) => change("name", event.target.value)} placeholder="e.g. Premium NPK Fertilizer"/></label><div className="admin-form-row"><label>Category<select required value={form.categoryId} onChange={(event) => change("categoryId", event.target.value)}><option value="">Select category</option>{categories.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>Brand<select value={form.brandId} onChange={(event) => change("brandId", event.target.value)}><option value="">No brand</option>{brands.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label></div><label>Description<textarea rows={3} maxLength={2000} value={form.description} onChange={(event) => change("description", event.target.value)} placeholder="Product details"/></label><div className="admin-form-row"><label>Pack size<input required value={form.packSize} onChange={(event) => change("packSize", event.target.value)} placeholder="1"/></label><label>Unit<input required value={form.unit} onChange={(event) => change("unit", event.target.value)} placeholder="kg bag"/></label></div><div className="admin-form-row"><label>Selling price (â‚¹)<input required type="number" min="0" step="0.01" value={form.price} onChange={(event) => change("price", event.target.value)}/></label><label>MRP (â‚¹)<input required type="number" min="0" step="0.01" value={form.mrp} onChange={(event) => change("mrp", event.target.value)}/></label></div><div className="admin-form-row"><label>Tax rate (%)<input type="number" min="0" max="100" step="0.01" value={form.taxRate} onChange={(event) => change("taxRate", event.target.value)}/></label><label>Minimum order qty<input required type="number" min="1" value={form.minimumOrderQuantity} onChange={(event) => change("minimumOrderQuantity", event.target.value)}/></label></div><div className="admin-form-row"><label>SKU<input required maxLength={80} value={form.sellerSku} onChange={(event) => change("sellerSku", event.target.value)}/></label><label>Available stock<input required type="number" min="0" value={form.stockOnHand} onChange={(event) => change("stockOnHand", event.target.value)}/></label></div><label>Serviceable PIN codes<input required pattern="[0-9]{6}(,\s*[0-9]{6})*" value={form.servicePinCodes} onChange={(event) => change("servicePinCodes", event.target.value)} placeholder="736101, 736121"/><small>Separate six-digit PIN codes with commas. Orders are accepted only for these PIN codes.</small></label><label>Catalogue status<select value={form.status} onChange={(event) => change("status", event.target.value as ProductStatus)}>{["APPROVED", "DRAFT", "PENDING_REVIEW", "REJECTED", "ARCHIVED"].map((status) => <option key={status}>{status}</option>)}</select></label></div></div><footer><button type="button" className="admin-secondary" onClick={onClose}>Cancel</button><button type="submit" className="admin-primary" disabled={busy}>{busy ? "Savingâ€¦" : editing ? "Save product" : "Create product"}</button></footer></form></section></div>;
}

function ProductThumb({ image, name }: { image: string | null; name: string }) { return <span className="admin-product-thumb">{image ? <Image src={`${API_ORIGIN}${image}`} alt="" fill unoptimized/> : <b>{name.slice(0, 1)}</b>}</span>; }
function StockAdjustmentEditor({ busy, onSave }: { busy: boolean; onSave: (value: { quantityDelta: number; reason: string; batchNumber?: string; expiresAt?: string }) => void }) {
  const [quantityDelta, setQuantityDelta] = useState("1");
  const [reason, setReason] = useState("");
  const [batchNumber, setBatchNumber] = useState("");
  const [expiresAt, setExpiresAt] = useState("");
  return <details className="admin-stock-adjust"><summary>Adjust stock</summary><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); onSave({ quantityDelta: Number(quantityDelta), reason: reason.trim(), batchNumber: batchNumber.trim() || undefined, expiresAt: expiresAt || undefined }); setReason(""); }}><label>Quantity change<input required type="number" step="1" value={quantityDelta} onChange={(event) => setQuantityDelta(event.target.value)}/></label><label>Reason<input required maxLength={500} value={reason} onChange={(event) => setReason(event.target.value)}/></label><label>Batch number<input maxLength={100} value={batchNumber} onChange={(event) => setBatchNumber(event.target.value)}/></label><label>Expiry date<input type="date" value={expiresAt} onChange={(event) => setExpiresAt(event.target.value)}/></label><button className="admin-primary" disabled={busy || !reason.trim()}>Save adjustment</button></form></details>;
}

function PurchasesPanel({ orders, suppliers, products, busy, onCreate, onApprove, onReceive }: { orders: PurchaseOrder[]; suppliers: Organization[]; products: AdminProduct[]; busy: boolean; onCreate: (value: { supplierOrganizationId: string; note: string; lines: { productId: string; quantity: number; unitCost: number }[] }) => void; onApprove: (id: string) => void; onReceive: (id: string, lines: { lineId: string; quantity: number }[]) => void }) {
  const [supplierId, setSupplierId] = useState("");
  const [productId, setProductId] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [unitCost, setUnitCost] = useState("");
  const [note, setNote] = useState("");
  const [lines, setLines] = useState<{ productId: string; quantity: number; unitCost: number }[]>([]);
  const addLine = () => {
    if (!productId || Number(quantity) < 1 || Number(unitCost) < 0 || lines.some((line) => line.productId === productId)) return;
    setLines((current) => [...current, { productId, quantity: Number(quantity), unitCost: Number(unitCost) }]);
    setProductId(""); setQuantity("1"); setUnitCost("");
  };
  return <>
    <section className="admin-panel"><PanelTitle title="Create purchase order" caption="Draft the supplier order, approve it, then receive stock in one or more audited receipts."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); if (!supplierId || !lines.length) return; onCreate({ supplierOrganizationId: supplierId, note: note.trim(), lines }); setLines([]); setNote(""); }}>
      <label>Approved supplier<select required value={supplierId} onChange={(event) => setSupplierId(event.target.value)}><option value="">Select supplier</option>{suppliers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <div className="admin-form-row"><label>Product<select value={productId} onChange={(event) => setProductId(event.target.value)}><option value="">Select product</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.packSize}</option>)}</select></label><label>Quantity<input type="number" min="1" step="1" value={quantity} onChange={(event) => setQuantity(event.target.value)}/></label><label>Unit cost<input type="number" min="0" step="0.01" value={unitCost} onChange={(event) => setUnitCost(event.target.value)}/></label><button type="button" className="admin-secondary" onClick={addLine} disabled={!productId || !unitCost}>Add line</button></div>
      {lines.length > 0 && <div className="admin-table-scroll"><table><thead><tr><th>Product</th><th>Quantity</th><th>Cost / unit</th><th>Total</th><th></th></tr></thead><tbody>{lines.map((line) => { const product = products.find((item) => item.id === line.productId); return <tr key={line.productId}><td>{product?.name}</td><td>{line.quantity}</td><td>{formatRupees(line.unitCost)}</td><td>{formatRupees(line.quantity * line.unitCost)}</td><td><button type="button" className="admin-danger" onClick={() => setLines((current) => current.filter((item) => item.productId !== line.productId))}>Remove</button></td></tr>; })}</tbody></table></div>}
      <label>Purchase note<input maxLength={1000} value={note} onChange={(event) => setNote(event.target.value)} placeholder="Optional terms or supplier reference"/></label><button className="admin-primary" disabled={busy || !supplierId || !lines.length}>Save purchase draft</button>
    </form></section>
    <section className="admin-panel admin-spaced"><PanelTitle title="Purchase orders" caption={`${orders.length} orders · receipt quantities update Agri-One inventory and supplier due`}/>{orders.length ? <div className="admin-table-scroll"><table><thead><tr><th>Purchase order</th><th>Supplier</th><th>Items received</th><th>Total ordered</th><th>Status</th><th>Workflow</th></tr></thead><tbody>{orders.map((order) => { const received = order.lines.reduce((sum, line) => sum + line.receivedQuantity, 0); const ordered = order.lines.reduce((sum, line) => sum + line.quantity, 0); return <tr key={order.id}><td><b>{order.orderNumber}</b><small className="admin-table-sub">{new Date(order.createdAt).toLocaleDateString()}</small></td><td>{order.supplier.name}</td><td>{received} / {ordered}</td><td>{formatRupees(Number(order.total))}</td><td><Status value={order.status}/></td><td><div className="admin-actions">{order.status === "DRAFT" && <button className="admin-approve" disabled={busy} onClick={() => onApprove(order.id)}>Approve</button>}{["APPROVED", "PARTIALLY_RECEIVED"].includes(order.status) && <button className="admin-primary" disabled={busy || ordered <= received} onClick={() => onReceive(order.id, order.lines.filter((line) => line.quantity > line.receivedQuantity).map((line) => ({ lineId: line.id, quantity: line.quantity - line.receivedQuantity })))}>Receive remaining</button>}</div></td></tr>; })}</tbody></table></div> : <Empty>No purchase orders yet. Create a draft above.</Empty>}</section>
  </>;
}

function FinancePanel({ data, busy, onCreateAccount, onCollect, onPaySupplier, onRefund, onExpense }: { data: FinanceData; busy: boolean; onCreateAccount: (value: { name: string; type: string; bankName?: string; accountNumberLast4?: string; openingBalance: number }) => void; onCollect: (value: { retailerId: string; orderId: string; accountId: string; amount: number; reference?: string; note?: string }) => void; onPaySupplier: (value: { purchaseOrderId: string; accountId: string; amount: number; reference?: string; note?: string }) => void; onRefund: (value: { receiptTransactionId: string; accountId: string; amount: number; reason: string }) => void; onExpense: (value: { accountId: string; category: string; amount: number; note: string; reference?: string }) => void }) {
  const [accountName, setAccountName] = useState("");
  const [accountType, setAccountType] = useState("CASH");
  const [bankName, setBankName] = useState("");
  const [lastFour, setLastFour] = useState("");
  const [openingBalance, setOpeningBalance] = useState("0");
  const [invoiceId, setInvoiceId] = useState("");
  const [receiptAccount, setReceiptAccount] = useState("");
  const [receiptAmount, setReceiptAmount] = useState("");
  const [receiptReference, setReceiptReference] = useState("");
  const [purchaseId, setPurchaseId] = useState("");
  const [paymentAccount, setPaymentAccount] = useState("");
  const [supplierAmount, setSupplierAmount] = useState("");
  const [supplierReference, setSupplierReference] = useState("");
  const [expenseAccount, setExpenseAccount] = useState("");
  const [expenseCategory, setExpenseCategory] = useState("");
  const [expenseAmount, setExpenseAmount] = useState("");
  const [expenseNote, setExpenseNote] = useState("");
  const [expenseReference, setExpenseReference] = useState("");
  const [refundId, setRefundId] = useState("");
  const [refundAccount, setRefundAccount] = useState("");
  const [refundAmount, setRefundAmount] = useState("");
  const [refundReason, setRefundReason] = useState("");
  const activeAccounts = data.accounts.filter((account) => account.isActive);
  const invoice = data.retailerInvoices.find((item) => item.orderId === invoiceId);
  const payable = data.supplierPayables.find((item) => item.purchaseOrderId === purchaseId);
  const refundReceipt = data.transactions.find((item) => item.id === refundId && item.type === "RETAILER_RECEIPT");
  const summary = data.summary;
  return <>
    <div className="admin-stat-grid">{[["Retailer due", formatRupees(summary.retailerDue)], ["Supplier due", formatRupees(summary.supplierDue)], ["Cash & bank", formatRupees(summary.cashAndBank)], ["Collections", formatRupees(summary.collections)], ["Business expenses", formatRupees(summary.expenses)]].map(([label, value]) => <article className="admin-stat admin-green" key={label}><span>₹</span><div><small>{label}</small><strong>{value}</strong><em>Live ledger total</em></div></article>)}</div>
    <section className="admin-panel"><PanelTitle title="Cash & bank accounts" caption="Opening balances and every posted transaction are kept in the account ledger."/><div className="admin-account-grid">{data.accounts.map((account) => <article key={account.id}><b>{account.name}</b><small>{account.type}{account.bankName ? ` · ${account.bankName}` : ""}{account.accountNumberLast4 ? ` ·••${account.accountNumberLast4}` : ""}</small><strong>{formatRupees(Number(account.currentBalance))}</strong></article>)}</div><details className="admin-finance-details"><summary>Create account</summary><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); onCreateAccount({ name: accountName.trim(), type: accountType, ...(accountType === "BANK" ? { bankName: bankName.trim(), ...(lastFour ? { accountNumberLast4: lastFour } : {}) } : {}), openingBalance: Number(openingBalance) }); setAccountName(""); }}><div className="admin-form-row"><label>Account name<input required maxLength={120} value={accountName} onChange={(event) => setAccountName(event.target.value)}/></label><label>Type<select value={accountType} onChange={(event) => setAccountType(event.target.value)}><option value="CASH">Cash</option><option value="BANK">Bank</option></select></label></div>{accountType === "BANK" && <div className="admin-form-row"><label>Bank name<input required maxLength={120} value={bankName} onChange={(event) => setBankName(event.target.value)}/></label><label>Account last four digits<input maxLength={4} pattern="[0-9]{4}" value={lastFour} onChange={(event) => setLastFour(event.target.value)}/></label></div>}<label>Opening balance<input type="number" min="0" step="0.01" value={openingBalance} onChange={(event) => setOpeningBalance(event.target.value)}/></label><button className="admin-primary" disabled={busy}>Save account</button></form></details></section>
    <div className="admin-overview-grid"><section className="admin-panel"><PanelTitle title="Retailer ledger" caption="Outstanding delivered retailer invoices"/>{data.retailerDues.length ? data.retailerDues.map((item) => <div className="admin-list-row" key={item.id}><b>{item.name}</b><strong>{formatRupees(Number(item.due))}</strong></div>) : <Empty>No retailer dues are outstanding.</Empty>}</section><section className="admin-panel"><PanelTitle title="Supplier ledger" caption="Received stock awaiting supplier payment"/>{data.supplierDues.length ? data.supplierDues.map((item) => <div className="admin-list-row" key={item.id}><b>{item.name}</b><strong>{formatRupees(Number(item.due))}</strong></div>) : <Empty>No supplier dues are outstanding.</Empty>}</section></div>
    <div className="admin-erp-form-grid">
      <section className="admin-panel"><PanelTitle title="Retailer payment collection" caption="Post full or partial receipts against delivered orders."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); if (!invoice) return; onCollect({ retailerId: invoice.retailerId, orderId: invoice.orderId, accountId: receiptAccount, amount: Number(receiptAmount), reference: receiptReference.trim() || undefined }); setReceiptAmount(""); setReceiptReference(""); }}><label>Open retailer invoice<select required value={invoiceId} onChange={(event) => { setInvoiceId(event.target.value); setReceiptAmount(""); }}><option value="">Select delivered order</option>{data.retailerInvoices.map((item) => <option key={item.orderId} value={item.orderId}>{item.retailerName} · {item.orderNumber} · due {formatRupees(Number(item.due))}</option>)}</select></label>{invoice && <div className="admin-inline-note">{invoice.retailerName} · remaining due {formatRupees(Number(invoice.due))}</div>}<label>Receive into<select required value={receiptAccount} onChange={(event) => setReceiptAccount(event.target.value)}><option value="">Select account</option>{activeAccounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Amount<input required type="number" min="0.01" max={invoice ? Number(invoice.due) : undefined} step="0.01" value={receiptAmount} onChange={(event) => setReceiptAmount(event.target.value)}/></label><label>Receipt reference<input maxLength={120} value={receiptReference} onChange={(event) => setReceiptReference(event.target.value)}/></label><button className="admin-primary" disabled={busy || !invoice || !receiptAccount}>Record receipt</button></form></section>
      <section className="admin-panel"><PanelTitle title="Supplier payment" caption="Pay against received quantities. Account balance is checked before posting."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); if (!payable) return; onPaySupplier({ purchaseOrderId: payable.purchaseOrderId, accountId: paymentAccount, amount: Number(supplierAmount), reference: supplierReference.trim() || undefined }); setSupplierAmount(""); setSupplierReference(""); }}><label>Open supplier payable<select required value={purchaseId} onChange={(event) => { setPurchaseId(event.target.value); setSupplierAmount(""); }}><option value="">Select received purchase</option>{data.supplierPayables.map((item) => <option key={item.purchaseOrderId} value={item.purchaseOrderId}>{item.supplierName} · {item.orderNumber} · due {formatRupees(Number(item.due))}</option>)}</select></label>{payable && <div className="admin-inline-note">{payable.supplierName} · remaining due {formatRupees(Number(payable.due))}</div>}<label>Pay from<select required value={paymentAccount} onChange={(event) => setPaymentAccount(event.target.value)}><option value="">Select account</option>{activeAccounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Amount<input required type="number" min="0.01" max={payable ? Number(payable.due) : undefined} step="0.01" value={supplierAmount} onChange={(event) => setSupplierAmount(event.target.value)}/></label><label>Payment reference<input maxLength={120} value={supplierReference} onChange={(event) => setSupplierReference(event.target.value)}/></label><button className="admin-primary" disabled={busy || !payable || !paymentAccount}>Record supplier payment</button></form></section>
      <section className="admin-panel"><PanelTitle title="Business expense" caption="Expense records reduce the selected account balance and appear in reports."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); onExpense({ accountId: expenseAccount, category: expenseCategory.trim(), amount: Number(expenseAmount), note: expenseNote.trim(), reference: expenseReference.trim() || undefined }); setExpenseAmount(""); setExpenseNote(""); setExpenseReference(""); }}><label>Pay from<select required value={expenseAccount} onChange={(event) => setExpenseAccount(event.target.value)}><option value="">Select account</option>{activeAccounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Expense category<input required maxLength={100} value={expenseCategory} onChange={(event) => setExpenseCategory(event.target.value)} placeholder="Rent, transport, utilities"/></label><label>Amount<input required type="number" min="0.01" step="0.01" value={expenseAmount} onChange={(event) => setExpenseAmount(event.target.value)}/></label><label>Description<input required maxLength={1000} value={expenseNote} onChange={(event) => setExpenseNote(event.target.value)}/></label><label>Reference<input maxLength={120} value={expenseReference} onChange={(event) => setExpenseReference(event.target.value)}/></label><button className="admin-primary" disabled={busy || !expenseAccount}>Record expense</button></form></section>
      <section className="admin-panel"><PanelTitle title="Payment correction / refund" caption="Post an audited refund against an original retailer receipt. The balance is checked before money leaves the account."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); if (!refundReceipt) return; onRefund({ receiptTransactionId: refundReceipt.id, accountId: refundAccount, amount: Number(refundAmount), reason: refundReason.trim() }); setRefundAmount(""); setRefundReason(""); }}><label>Original retailer receipt<select required value={refundId} onChange={(event) => setRefundId(event.target.value)}><option value="">Select receipt to correct</option>{data.transactions.filter((item) => item.type === "RETAILER_RECEIPT").map((item) => <option key={item.id} value={item.id}>{item.partyOrganization?.name ?? "Retailer"} · {item.customerOrder?.orderNumber ?? "Order"} · {formatRupees(Number(item.amount))}</option>)}</select></label><label>Refund from<select required value={refundAccount} onChange={(event) => setRefundAccount(event.target.value)}><option value="">Select account</option>{activeAccounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Refund amount<input required type="number" min="0.01" step="0.01" value={refundAmount} onChange={(event) => setRefundAmount(event.target.value)}/></label><label>Correction reason<input required maxLength={500} value={refundReason} onChange={(event) => setRefundReason(event.target.value)}/></label><button className="admin-danger" disabled={busy || !refundReceipt || !refundAccount}>Record refund</button></form></section>
    </div>
    <section className="admin-panel admin-spaced"><PanelTitle title="Financial transactions" caption="Immutable receipts, supplier payments, expenses, refunds, and opening balances."/><div className="admin-table-scroll"><table><thead><tr><th>Date</th><th>Transaction</th><th>Party / reference</th><th>Account</th><th>Amount</th></tr></thead><tbody>{data.transactions.map((item) => <tr key={item.id}><td>{new Date(item.transactionDate).toLocaleDateString()}</td><td><b>{item.type.replaceAll("_", " ")}</b><small className="admin-table-sub">{item.category ?? item.note ?? ""}</small></td><td>{item.partyOrganization?.name ?? item.customerOrder?.orderNumber ?? item.purchaseOrder?.orderNumber ?? item.reference ?? "—"}</td><td>{item.account.name}</td><td><b>{formatRupees(Number(item.amount))}</b></td></tr>)}</tbody></table>{!data.transactions.length && <Empty>No finance transactions recorded.</Empty>}</div></section>
  </>;
}

function StaffPanel({ staff, busy, isSuperAdmin, onCreate, onStatus, onPermissions }: { staff: Account[]; busy: boolean; isSuperAdmin: boolean; onCreate: (value: { name: string; email: string; phone?: string; password: string; role: string; permissions?: string[] }) => void; onStatus: (id: string, status: "ACTIVE" | "DISABLED") => void; onPermissions: (id: string, permissions: string[]) => void }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("WAREHOUSE");
  const permissions = ["CATALOG", "RETAILERS", "ORDERS", "INVENTORY", "FINANCE", "DELIVERY", "REPORTS", "NOTIFICATIONS", "SETTINGS", "USERS", "PURCHASING", "STAFF", "ACTIVITY"];
  const [selectedPermissions, setSelectedPermissions] = useState<string[]>([]);
  return <><section className="admin-panel"><PanelTitle title="Create staff account" caption="Operations roles are scoped. Scoped admin accounts receive only the checked permissions."/><form className="admin-form-fields" onSubmit={(event) => { event.preventDefault(); onCreate({ name: name.trim(), email: email.trim(), phone: phone.trim() || undefined, password, role, ...(role === "ADMIN" ? { permissions: selectedPermissions } : {}) }); setName(""); setEmail(""); setPhone(""); setPassword(""); setSelectedPermissions([]); }}><div className="admin-form-row"><label>Full name<input required maxLength={120} value={name} onChange={(event) => setName(event.target.value)}/></label><label>Email<input required type="email" maxLength={254} value={email} onChange={(event) => setEmail(event.target.value)}/></label></div><div className="admin-form-row"><label>Phone<input type="tel" value={phone} onChange={(event) => setPhone(event.target.value)}/></label><label>Role<select value={role} onChange={(event) => setRole(event.target.value)}><option value="WAREHOUSE">Warehouse</option><option value="DELIVERY">Delivery</option><option value="FINANCE">Finance</option><option value="SUPPORT">Support</option>{isSuperAdmin && <option value="ADMIN">Scoped admin</option>}</select></label></div><label>Temporary password<input required type="password" minLength={12} maxLength={128} value={password} onChange={(event) => setPassword(event.target.value)} placeholder="12+ characters, upper/lowercase and a number"/></label>{role === "ADMIN" && <fieldset className="admin-permission-fieldset"><legend>Allowed modules</legend>{permissions.map((permission) => <label key={permission}><input type="checkbox" checked={selectedPermissions.includes(permission)} onChange={(event) => setSelectedPermissions((current) => event.target.checked ? [...current, permission] : current.filter((item) => item !== permission))}/>{permission}</label>)}</fieldset>}<button className="admin-primary" disabled={busy}>Create staff account</button></form></section><section className="admin-panel admin-spaced"><PanelTitle title="Staff accounts" caption="Disable access or update permissions for scoped administrators."/><div className="admin-table-scroll"><table><thead><tr><th>Staff</th><th>Role</th><th>Permissions</th><th>Status</th><th>Actions</th></tr></thead><tbody>{staff.map((user) => <tr key={user.id}><td><b>{user.name}</b><small className="admin-table-sub">{user.email}{user.phone ? ` · ${user.phone}` : ""}</small></td><td>{user.role}{user.isSuperAdmin ? " · Super admin" : ""}</td><td>{user.isSuperAdmin ? "All modules" : user.role === "ADMIN" ? (user.adminPermissions ?? []).join(", ") || "No modules assigned" : "Role scoped"}</td><td><Status value={user.status}/></td><td><button className={user.status === "ACTIVE" ? "admin-danger" : "admin-approve"} disabled={busy || user.isSuperAdmin} onClick={() => onStatus(user.id, user.status === "ACTIVE" ? "DISABLED" : "ACTIVE")}>{user.status === "ACTIVE" ? "Disable" : "Enable"}</button>{isSuperAdmin && user.role === "ADMIN" && !user.isSuperAdmin && <button className="admin-secondary" onClick={() => { const input = window.prompt(`Admin permission keys:\n${permissions.join(", ")}`, (user.adminPermissions ?? []).join(",")); if (input !== null) onPermissions(user.id, input.split(",").map((item) => item.trim().toUpperCase()).filter(Boolean)); }}>Edit permissions</button>}</td></tr>)}</tbody></table>{!staff.length && <Empty>No staff accounts yet.</Empty>}</div></section></>;
}

function ReturnsPanel({ returns, busy, onReview }: { returns: ReturnRecord[]; busy: boolean; onReview: (orderNumber: string, returnId: string, status: string) => void }) {
  return <section className="admin-panel"><PanelTitle title="Returns & claims" caption="Review retailer requests. Approvals are audited and closed requests cannot be reopened."/><div className="admin-table-scroll"><table><thead><tr><th>Requested</th><th>Order</th><th>Retailer</th><th>Order value</th><th>Reason</th><th>Status</th><th>Review</th></tr></thead><tbody>{returns.map((item) => <tr key={item.id}><td>{new Date(item.requestedAt).toLocaleDateString()}</td><td><b>{item.customerOrder.orderNumber}</b></td><td>{item.customerOrder.retailer.name}<small className="admin-table-sub">{item.customerOrder.retailer.phone ?? ""}</small></td><td>{formatRupees(Number(item.customerOrder.total))}</td><td>{item.reason}{item.reviewReason && <small className="admin-table-sub">{item.reviewReason}</small>}</td><td><Status value={item.status}/></td><td>{item.status === "REQUESTED" && <div className="admin-actions"><button className="admin-approve" disabled={busy} onClick={() => onReview(item.customerOrder.orderNumber, item.id, "APPROVED")}>Approve</button><button className="admin-danger" disabled={busy} onClick={() => onReview(item.customerOrder.orderNumber, item.id, "REJECTED")}>Reject</button></div>}{item.status === "APPROVED" && <button className="admin-approve" disabled={busy} onClick={() => onReview(item.customerOrder.orderNumber, item.id, "COMPLETED")}>Complete return</button>}</td></tr>)}</tbody></table>{!returns.length && <Empty>No returns or claims are waiting.</Empty>}</div></section>;
}

function ActivityPanel({ events, errors }: { events: AuditRow[]; errors: ErrorRecord[] }) {
  return <><section className="admin-panel"><PanelTitle title="Activity log" caption="Audited changes made across orders, accounts, inventory, finance and platform settings."/><div className="admin-table-scroll"><table><thead><tr><th>Date</th><th>Actor</th><th>Action</th><th>Record</th><th>Change details</th></tr></thead><tbody>{events.map((event) => <tr key={event.id}><td>{new Date(event.createdAt).toLocaleString()}</td><td>{event.actor?.name ?? "System"}<small className="admin-table-sub">{event.actor?.role ?? "Automated"}</small></td><td><b>{event.action.replaceAll("_", " ")}</b></td><td>{event.entityType}<small className="admin-table-sub">{event.entityId}</small></td><td><details><summary>View</summary><pre className="admin-audit-json">{JSON.stringify({ before: event.before, after: event.after }, null, 2)}</pre></details></td></tr>)}</tbody></table>{!events.length && <Empty>No audited activity is available.</Empty>}</div></section><section className="admin-panel admin-spaced"><PanelTitle title="Server error log" caption="Unexpected API failures only. Request bodies, credentials and stack traces are not stored here."/><div className="admin-table-scroll"><table><thead><tr><th>Date</th><th>Request</th><th>Result</th><th>Error type</th><th>Actor</th><th>Request ID</th></tr></thead><tbody>{errors.map((error) => <tr key={error.id}><td>{new Date(error.createdAt).toLocaleString()}</td><td>{error.method} {error.path}</td><td><Status value={`HTTP_${error.statusCode}`}/></td><td>{error.errorType}</td><td>{error.actor?.name ?? "Anonymous"}</td><td><code>{error.requestId}</code></td></tr>)}</tbody></table>{!errors.length && <Empty>No server errors have been recorded.</Empty>}</div></section></>;
}
function Status({ value }: { value: string }) { return <span className={`admin-status status-${value.toLowerCase().replaceAll("_", "-")}`}>{value.replaceAll("_", " ")}</span>; }
function PanelTitle({ title, caption, action, onAction }: { title: string; caption?: string; action?: string; onAction?: () => void }) { return <div className="admin-panel-title"><div><h2>{title}</h2>{caption && <p>{caption}</p>}</div>{action && <button onClick={onAction}>{action} â†’</button>}</div>; }
function Empty({ children }: { children: ReactNode }) { return <div className="admin-empty">{children}</div>; }

function SupportTicketsPanel({ tickets, busy, onUpdate }: { tickets: SupportTicket[]; busy: boolean; onUpdate: (id: string, status: SupportTicket["status"], reply: string) => void }) {
  return <section className="admin-panel"><PanelTitle title="Retailer complaints" caption="Review and reply to support tickets submitted from the mobile app."/>{tickets.map(ticket => <SupportTicketCard key={ticket.id} ticket={ticket} busy={busy} onUpdate={onUpdate}/>)}{tickets.length === 0 && <Empty>No retailer support tickets have been submitted.</Empty>}</section>;
}

function SupportTicketCard({ ticket, busy, onUpdate }: { ticket: SupportTicket; busy: boolean; onUpdate: (id: string, status: SupportTicket["status"], reply: string) => void }) {
  const [status, setStatus] = useState<SupportTicket["status"]>(ticket.status);
  const [reply, setReply] = useState(ticket.adminReply ?? "");
  return <article className="admin-product-management" style={{ padding: 14, marginBottom: 12 }}><div className="admin-panel-title"><div><h2>{ticket.subject}</h2><p>{ticket.organization.name} Â· {ticket.organization.email ?? ticket.organization.phone ?? "No contact"} Â· {new Date(ticket.createdAt).toLocaleString()}</p></div><Status value={ticket.status}/></div><p style={{ whiteSpace: "pre-wrap" }}>{ticket.message}</p><label>Reply to retailer<textarea rows={3} maxLength={3000} value={reply} onChange={event => setReply(event.target.value)} placeholder="Write a response" style={{ display: "block", width: "100%", marginTop: 6 }}/></label><div className="admin-form-row" style={{ marginTop: 10 }}><label>Status<select value={status} onChange={event => setStatus(event.target.value as SupportTicket["status"])}>{["OPEN", "IN_PROGRESS", "RESOLVED", "CLOSED"].map(value => <option key={value}>{value}</option>)}</select></label><button className="admin-primary" disabled={busy} onClick={() => onUpdate(ticket.id, status, reply)}>{busy ? "Savingâ€¦" : "Save reply"}</button></div></article>;
}
